  { name: 'Unity Bank', code: '215' },
  { name: 'Wema Bank', code: '035' },
  { name: 'Zenith Bank', code: '057' },
  { name: 'Kuda Bank', code: '50211' },
  { name: 'Opay', code: '100004' },
  { name: 'Palmpay', code: '100033' },
  { name: 'Moniepoint', code: '50515' },
];

async function getMonnifyToken(apiKey: string, secretKey: string): Promise<string> {
  const credential = btoa(`${apiKey}:${secretKey}`);
  console.log('[Monnify] Attempting auth, credential length:', credential.length);

  const res = await fetch(`${SANDBOX_BASE}/api/v1/auth/login`, {
    method: 'POST',
    headers: {
      'Authorization': `Basic ${credential}`,
      'Content-Type': 'application/json',
    },
  });

  const text = await res.text();
  console.log('[Monnify] Auth response status:', res.status, 'body:', text);

  if (!res.ok) {
    throw new Error(`Monnify auth failed (${res.status}): ${text}`);
  }

  const data = JSON.parse(text);
  if (!data.requestSuccessful || !data.responseBody?.accessToken) {
    throw new Error(`Monnify auth unsuccessful: ${text}`);
  }

  return data.responseBody.accessToken;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 200, headers: CORS_HEADERS });
  }

  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  // Log secret presence (never log actual values)
  console.log('[Monnify] Secrets present — API_KEY:', !!apiKey, 'length:', apiKey?.length ?? 0, '| SECRET_KEY:', !!secretKey, 'length:', secretKey?.length ?? 0);
  console.log('[Monnify] CONTRACT_CODE present:', !!contractCode, 'length:', contractCode?.length ?? 0);

  if (!apiKey || !secretKey) {
    return new Response(
      JSON.stringify({ error: true, message: 'Monnify credentials not configured' }),
      { status: 500, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
    );
  }

  const url = new URL(req.url);
  const path = url.pathname.replace(/^\/monnify-verify-account/, '') || '/';

  // ── GET /banks ──────────────────────────────────────────────────────────────
  // Always returns 200 — falls back to hardcoded list if anything fails
  if (req.method === 'GET' && path === '/banks') {
    try {
      const accessToken = await getMonnifyToken(apiKey, secretKey);
      const banksRes = await fetch(`${SANDBOX_BASE}/api/v1/sdk/transactions/banks`, {
        headers: { 'Authorization': `Bearer ${accessToken}` },
      });
      const banksText = await banksRes.text();
      console.log('[Monnify] Banks response status:', banksRes.status, 'body:', banksText.slice(0, 300));

      if (!banksRes.ok) throw new Error(`Banks fetch failed: ${banksRes.status}`);
      const banksData = JSON.parse(banksText);
      if (!banksData.requestSuccessful || !Array.isArray(banksData.responseBody)) throw new Error('Invalid banks shape');

      const banks = banksData.responseBody.map((b: { name: string; code: string }) => ({ name: b.name, code: b.code }));
      return new Response(JSON.stringify(banks), { status: 200, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } });
    } catch (err) {
      console.warn('[Monnify] Banks fetch failed, using fallback:', err instanceof Error ? err.message : String(err));
      return new Response(JSON.stringify(FALLBACK_BANKS), { status: 200, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } });
    }
  }

  // ── POST / — account name lookup ────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const body = await req.json();
      const { accountNumber, bankCode } = body;
      console.log('[Monnify] Verify request — accountNumber:', accountNumber, 'bankCode:', bankCode);

      if (!accountNumber || !bankCode) {
        return new Response(
          JSON.stringify({ error: true, message: 'accountNumber and bankCode are required' }),
          { status: 400, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
        );
      }

      const accessToken = await getMonnifyToken(apiKey, secretKey);

      // First attempt: disbursements validate
      let validateRes = await fetch(
        `${SANDBOX_BASE}/api/v1/disbursements/account/validate?accountNumber=${encodeURIComponent(accountNumber)}&bankCode=${encodeURIComponent(bankCode)}`,
        { method: 'GET', headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' } }
      );
      let validateText = await validateRes.text();
      console.log('[Monnify] Validate (disbursements) status:', validateRes.status, 'body:', validateText);

      let validateData = JSON.parse(validateText);

      // Second attempt: reserved-accounts lookup with contract code
      if ((!validateRes.ok || !validateData.requestSuccessful) && contractCode) {
        console.log('[Monnify] Retrying with reserved-accounts/lookup endpoint');
        validateRes = await fetch(
          `${SANDBOX_BASE}/api/v1/bank-transfer/reserved-accounts/lookup?accountNumber=${encodeURIComponent(accountNumber)}&bankCode=${encodeURIComponent(bankCode)}&contractCode=${encodeURIComponent(contractCode)}`,
          { method: 'GET', headers: { 'Authorization': `Bearer ${accessToken}`, 'Content-Type': 'application/json' } }
        );
        validateText = await validateRes.text();
        console.log('[Monnify] Validate (reserved-accounts) status:', validateRes.status, 'body:', validateText);
        validateData = JSON.parse(validateText);
      }

      if (!validateRes.ok || !validateData.requestSuccessful) {
        const message =
          validateData?.responseMessage ||
          validateData?.responseBody?.message ||
          validateData?.message ||
          validateText;
        console.error('[Monnify] Validate failed:', message);
        return new Response(
          JSON.stringify({ error: true, message }),
          { status: 400, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
        );
      }

      const { accountName, accountNumber: accNum, bankCode: bCode } = validateData.responseBody;
      console.log('[Monnify] Validate success — accountName:', accountName);

      return new Response(
        JSON.stringify({ accountName, accountNumber: accNum, bankCode: bCode }),
        { status: 200, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
      );
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      console.error('[Monnify] POST handler error:', message);
      return new Response(
        JSON.stringify({ error: true, message }),
        { status: 500, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
      );
    }
  }

  return new Response(
    JSON.stringify({ error: true, message: 'Not found' }),
    { status: 404, headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' } }
  );
});
```

