              <Text style={styles.legalLink}>Terms of Service</Text>
              {' and '}
              <Text style={styles.legalLink}>Privacy Policy</Text>
              {'.'}
            </Text>
          </View>
        ) : null}
      </ScrollView>
    </KeyboardAvoidingView>
