### `index.ts`
```ts
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { getAuthenticatedUser, getServiceClient } from './auth.ts';
import { set, zrem, KEYS } from './redis.ts';
import { broadcastToChannel } from './broadcast.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const user = await getAuthenticatedUser(req);
    const doctorId = user.id;

    const body = await req.json();
    const { request_id } = body;

    if (!request_id) {
      return new Response(
        JSON.stringify({ error: 'Missing required field: request_id' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const serviceClient = getServiceClient();

    // Validate request exists and is pending — fetch all fields needed for session
    const { data: existingRequest, error: fetchError } = await serviceClient
      .from('coverage_requests')
      .select('id, status, requester_id, hospital_name, hospital_address, shift_date, shift_start, shift_end, shift_type, coverage_type')
      .eq('id', request_id)
      .single();

    if (fetchError || !existingRequest) {
      return new Response(
        JSON.stringify({ error: 'Request not found' }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    if (existingRequest.status !== 'pending') {
      return new Response(
        JSON.stringify({ error: 'ALREADY_MATCHED', message: 'This request is no longer available.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Atomic SETNX lock — only one doctor wins
    const lockResult = await set(KEYS.lock(request_id), doctorId, { ex: 10, nx: true });

    if (lockResult === null) {
      return new Response(
        JSON.stringify({ error: 'RACE_LOST', message: 'Another doctor accepted this request first.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Lock acquired — attempt atomic DB update (only succeeds if still pending)
    const now = new Date().toISOString();
    const { data: updatedRows, error: updateError } = await serviceClient
      .from('coverage_requests')
      .update({
        status: 'matched',
        matched_doctor_id: doctorId,
        matched_at: now,
        updated_at: now,
      })
      .eq('id', request_id)
      .eq('status', 'pending')
      .select('id');

    if (updateError) throw new Error(updateError.message);

    if (!updatedRows || updatedRows.length === 0) {
      return new Response(
        JSON.stringify({ error: 'ALREADY_MATCHED', message: 'Request was matched by another doctor.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // Remove from Redis queue
    await zrem(KEYS.REQUEST_QUEUE, request_id);

    // Fetch doctor profile + doctor_profiles + requester profile in parallel
    const [{ data: doctorProfile }, { data: doctorDetails }, { data: requesterProfile }] = await Promise.all([
      serviceClient
        .from('profiles')
        .select('first_name, last_name, phone')
        .eq('id', doctorId)
        .single(),
      serviceClient
        .from('doctor_profiles')
        .select('mdcn_number, rating, reliability_score')
        .eq('user_id', doctorId)
        .single(),
      serviceClient
        .from('profiles')
        .select('first_name, last_name, phone')
        .eq('id', existingRequest.requester_id)
        .single(),
    ]);

    const doctorPayload = {
      name: `Dr. ${doctorProfile?.first_name ?? ''} ${doctorProfile?.last_name ?? ''}`.trim(),
      mdcn: doctorDetails?.mdcn_number ?? 'MDCN/R/00000',
      rating: doctorDetails?.rating ?? 5.0,
      reliability: doctorDetails?.reliability_score ?? 100,
    };

    // Broadcast MATCH_CONFIRMED + EVICT_REQUEST in parallel
    await Promise.all([
      broadcastToChannel(
        `requester:${request_id}`,
        'MATCH_CONFIRMED',
        { doctor: doctorPayload }
      ),
      broadcastToChannel(
        'dispatch:lagos',
        'EVICT_REQUEST',
        { request_id }
      ),
    ]);

    // Insert coverage session
    const sessionData = {
      request_id,
      doctor_id: doctorId,
      requester_id: existingRequest.requester_id,
      hospital_name: existingRequest.hospital_name,
      hospital_address: existingRequest.hospital_address,
      shift_date: existingRequest.shift_date,
      shift_start: existingRequest.shift_start,
      shift_end: existingRequest.shift_end,
      shift_type: existingRequest.shift_type,
      coverage_type: existingRequest.coverage_type ?? existingRequest.shift_type,
      status: 'upcoming',
      doctor_name: `Dr. ${doctorProfile?.first_name ?? ''} ${doctorProfile?.last_name ?? ''}`.trim(),
      doctor_mdcn: doctorDetails?.mdcn_number ?? '',
      doctor_rating: doctorDetails?.rating ?? 5.0,
      doctor_reliability: doctorDetails?.reliability_score ?? 100,
      doctor_phone: doctorProfile?.phone ?? null,
      requester_name: `${requesterProfile?.first_name ?? ''} ${requesterProfile?.last_name ?? ''}`.trim(),
      requester_phone: requesterProfile?.phone ?? null,
    };

    const { data: sessionRow, error: sessionError } = await serviceClient
      .from('coverage_sessions')
      .insert(sessionData)
      .select()
      .single();

    if (sessionError) {
      console.error('[accept-request] Failed to create coverage session:', sessionError.message);
      // Non-fatal — don't fail the whole accept
    } else if (sessionRow) {
      // Broadcast SESSION_CREATED to both doctor and requester channels
      await Promise.all([
        broadcastToChannel(`doctor:${doctorId}`, 'SESSION_CREATED', { session_id: sessionRow.id, ...sessionData }),
        broadcastToChannel(`requester:${existingRequest.requester_id}`, 'SESSION_CREATED', { session_id: sessionRow.id, ...sessionData }),
      ]);
    }

    return new Response(
      JSON.stringify({ success: true, request_id, matched: true }),
      { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    const status = message.includes('Missing Authorization') || message.includes('Invalid or expired') ? 401 : 500;
    return new Response(
      JSON.stringify({ error: message }),
      { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});
```

