export const KEYS = {
  ONLINE_DOCTORS: 'online_doctors',
  REQUEST_QUEUE: 'request_queue',
  lock: (requestId: string) => `lock:${requestId}`,
  heartbeat: (doctorId: string) => `heartbeat:${doctorId}`,
};

export async function redisCommand(command: string, ...args: (string | number)[]): Promise<unknown> {
  const url = Deno.env.get('UPSTASH_REDIS_REST_URL')!;
  const token = Deno.env.get('UPSTASH_REDIS_REST_TOKEN')!;
  const response = await fetch(`${url}/${[command, ...args].map(encodeURIComponent).join('/')}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!response.ok) throw new Error(`Redis error: ${response.status} ${await response.text()}`);
  return (await response.json()).result;
}

