router.push({ pathname: '/(onboarding)/requester/basic-profile', params: { from: 'doctor-account' } } as any);
```

Then in each onboarding screen's `handleBack`, read `useLocalSearchParams` and fall back to the correct account tab:

```ts
// doctor/basic-profile.tsx
import { useRouter, useLocalSearchParams } from 'expo-router';
