const handleBack = () => {
  if (from === 'requester-account') {
    router.replace('/(requester)/(account)' as any);
  } else if (profile?.doctor_onboarding_complete) {
    router.replace('/(doctor)/(home)' as any);
  } else {
    router.replace('/(auth)/role-select');
  }
};
```

