## Everything Is Now 100% Locked

### Database Migration
```sql
ALTER TABLE coverage_sessions
  ADD COLUMN IF NOT EXISTS coverage_length        integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS environment            text NOT NULL DEFAULT 'Normal',
  ADD COLUMN IF NOT EXISTS price                  numeric(12,2) NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS hourly_rate_kobo       integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS current_day            integer NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS day_logs               jsonb NOT NULL DEFAULT '[]',
  ADD COLUMN IF NOT EXISTS payment_initiated_at   timestamptz,
  ADD COLUMN IF NOT EXISTS payment_deadline_at    timestamptz,
  ADD COLUMN IF NOT EXISTS payment_status         text NOT NULL DEFAULT 'unpaid',
  ADD COLUMN IF NOT EXISTS monnify_reference      text,
  ADD COLUMN IF NOT EXISTS monnify_account_number text,
  ADD COLUMN IF NOT EXISTS monnify_bank_name      text,
  ADD COLUMN IF NOT EXISTS monnify_account_name   text;
```

`hourly_rate_kobo` is stored as an integer (kobo) to avoid all floating point issues. ₦2,000/hr = `200000` kobo.

---

### Billing Engine Function (pseudo-code, will be implemented in the edge function)

```typescript
function computeDayBill(
  workedSeconds: number,
  bookedSeconds: number,
  hourlyRateKobo: number,
  isHomecare: boolean,
  is24hrStraight: boolean
): number {

  const workedMinutes = workedSeconds / 60;
  const bookedMinutes = bookedSeconds / 60;
  const graceMinutes = bookedMinutes + 15;

  // 24hr straight shift rule (single continuous only)
  if (is24hrStraight) {
    if (workedMinutes < 22 * 60) {
      // fall through to normal billing
    } else if (workedMinutes <= 25 * 60) {
      return 3600000; // ₦36,000 flat in kobo
    } else {
      const extraHours = (workedMinutes / 60) - 24;
      return 3600000 + Math.round(extraHours * (3600000 / 24));
    }
  }

  // Grace period check
  let billableMinutes: number;
  if (workedMinutes <= graceMinutes) {
    // Within grace — charge booked duration exactly
    billableMinutes = bookedMinutes;
  } else {
    // Grace forfeited — full actual time through Step 2
    if (workedMinutes <= 60) {
      billableMinutes = 60;
    } else {
      const excess = workedMinutes - 60;
      billableMinutes = 60 + Math.ceil(excess / 15) * 15;
    }
  }

  const billableHours = billableMinutes / 60;
  return Math.round(billableHours * hourlyRateKobo);
}

// Multi-day total
function computeTotalBill(dayLogs: DayLog[], hourlyRateKobo: number, bookedSecondsPerDay: number): number {
  return dayLogs.reduce((sum, log) => {
    return sum + computeDayBill(log.duration_seconds, bookedSecondsPerDay, hourlyRateKobo, false, false);
  }, 0);
}
```

