import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[end-shift] Broadcast OK to ${channel} event=${event}`);
  }
}

type DayLog = {
  day: number;
  started_at: string;
  paused_at: string | null;
  duration_seconds: number;
};

type MonnifyResult = {
  accountNumber: string;
  bankName: string;
  accountName: string;
  reference: string;
};

async function createMonnifyReservedAccount(
  sessionId: string,
  hospitalName: string,
  requesterName: string,
  requesterEmail: string,
  subaccountCode: string | null
): Promise<MonnifyResult> {
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    throw new Error('Monnify credentials not configured');
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';

  const credentials = btoa(`${apiKey}:${secretKey}`);

  const body: Record<string, unknown> = {
    accountReference: sessionId,
    accountName: `FlashLocum / ${hospitalName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: requesterEmail,
    customerName: requesterName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode && subaccountCode.trim()) {
    body.incomeSplitConfig = [
      {
        subAccountCode: subaccountCode,
        feePercentage: 0,
        splitPercentage: 85,
        feeBearer: false,
      },
    ];
    console.log(`[end-shift] Using incomeSplitConfig with subAccountCode=${subaccountCode}`);
  } else {
    console.log('[end-shift] No subaccount_code found, omitting incomeSplitConfig');
  }

  const response = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  const data = await response.json();
  console.log('[end-shift] Monnify response:', JSON.stringify(data));

  if (!response.ok || !data.requestSuccessful) {
    throw new Error(`Monnify error: ${data.responseMessage ?? response.status}`);
  }

  const rb = data.responseBody;
  const account = rb.accounts?.[0];

  return {
    accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
    bankName: account?.bankName ?? rb.bankName ?? '',
    accountName: rb.accountName ?? '',
    reference: rb.accountReference ?? sessionId,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405, headers: corsHeaders });
  }

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: req.headers.get('Authorization')! } } }
  );

  const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(JSON.stringify({ error: 'Missing field: session_id' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { data: session, error: fetchError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (fetchError || !session) {
    return new Response(JSON.stringify({ error: 'Session not found' }), {
      status: 404,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (session.requester_id !== user.id) {
    return new Response(JSON.stringify({ error: 'Forbidden: only the requester can end a shift' }), {
      status: 403,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (session.status !== 'active' && session.status !== 'paused') {
    return new Response(JSON.stringify({ error: `Cannot end a shift with status: ${session.status}` }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const currentDay = session.current_day ?? 1;
  let dayLogs: DayLog[] = session.day_logs ?? [];

  if (session.status === 'active') {
    const todayLogIndex = dayLogs.findIndex((l) => l.day === currentDay);
    if (todayLogIndex !== -1) {
      const todayLog = dayLogs[todayLogIndex];
      const durationSeconds = Math.floor((now.getTime() - new Date(todayLog.started_at).getTime()) / 1000);
      dayLogs = [...dayLogs];
      dayLogs[todayLogIndex] = {
        ...todayLog,
        paused_at: nowIso,
        duration_seconds: durationSeconds,
      };
    }
  }

  const hourlyRateKobo = session.hourly_rate_kobo ?? 0;
  const totalSeconds = dayLogs.reduce((sum: number, log: DayLog) => sum + (log.duration_seconds ?? 0), 0);
  const totalHours = totalSeconds / 3600;
  const cumulativeCostKobo = Math.ceil(totalHours * hourlyRateKobo);
  const cumulativeCostNaira = cumulativeCostKobo / 100;

  const finalAmountNaira = cumulativeCostNaira >= 1 ? cumulativeCostNaira : (session.price ?? 0);

  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code')
    .eq('id', session.doctor_id)
    .maybeSingle();

  const subaccountCode = doctorProfile?.subaccount_code ?? null;

  const { data: { user: requesterUser } } = await supabaseAdmin.auth.admin.getUserById(user.id);
  const requesterEmail = requesterUser?.email ?? 'noreply@flashlocum.com';

  const deadlineAt = new Date(now.getTime() + 15 * 60 * 1000).toISOString();

  let monnifyFields: { ... };

  try {
    const monnifyData = await createMonnifyReservedAccount(
      session_id, session.hospital_name, session.requester_name, requesterEmail, subaccountCode
    );
    monnifyFields = {
      monnify_reference: monnifyData.reference,
      monnify_account_reference: monnifyData.reference,
      monnify_account_number: monnifyData.accountNumber,
      monnify_bank_name: monnifyData.bankName,
      monnify_account_name: monnifyData.accountName,
    };
  } catch (err) {
    // Non-fatal — sets all monnify fields to null
    monnifyFields = { monnify_reference: null, monnify_account_reference: null,
      monnify_account_number: null, monnify_bank_name: null, monnify_account_name: null,
      monnify_error: 'Virtual account creation failed — please contact support' };
  }

  const { data: updated, error: updateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update({
      status: 'payment_pending',
      ended_at: nowIso,
      price: finalAmountNaira,
      day_logs: dayLogs,
      payment_initiated_at: nowIso,
      payment_deadline_at: deadlineAt,
      payment_status: 'pending',
      ...monnifyFields,
      updated_at: nowIso,
    })
    .eq('id', session_id)
    .select()
    .single();

  if (updateError) {
    return new Response(JSON.stringify({ error: updateError.message }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  await broadcastToChannel(`session:${session_id}`, 'SHIFT_ENDED', { session: updated });

  return new Response(JSON.stringify({
    session: updated,
    account_number: monnifyFields.monnify_account_number,
    bank_name: monnifyFields.monnify_bank_name,
    account_name: monnifyFields.monnify_account_name,
    amount_naira: finalAmountNaira,
    deadline_at: deadlineAt,
  }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
});
