## 3. `submit-request/index.ts` — Pricing/Rate Calculation Section

```typescript
interface PricingConfig {
  home_care_rate: number;
  day_rate_short: number;
  day_rate_medium: number;
  day_rate_long: number;
  night_rate: number;
  flat_24h_fee: number;
  busy_multiplier: number;
}

function calculateDurationAndPrice(
  start_time: string,
  end_time: string,
  coverage_length: number,
  coverage_type: string,
  environment: string,
  pricing: PricingConfig
): { per_day_hours: number; total_hours: number; price: number } {
  const startHour = parseHour(start_time);
  const endHour = parseHour(end_time);

  // --- Duration ---
  let rawPerDay: number;
  if (endHour === startHour) {
    rawPerDay = 24;
  } else if (endHour > startHour) {
    rawPerDay = endHour - startHour;
  } else {
    rawPerDay = (24 - startHour) + endHour;
  }
  const per_day_hours = roundQuarter(rawPerDay);
  const total_hours = per_day_hours * coverage_length;

  // --- Pricing ---
  let price: number;

  if (coverage_type === 'Home Care') {
    price = Math.round(total_hours * Number(pricing.home_care_rate));
  } else {
    const busyMultiplier = environment === 'Busy' ? Number(pricing.busy_multiplier) : 1.0;
    const isStraight = per_day_hours >= 24;

    if (isStraight) {
      const fullBlocks = Math.floor(total_hours / 24);
      const remainder = total_hours - fullBlocks * 24;
      price = Math.round(
        (fullBlocks * Number(pricing.flat_24h_fee) + remainder * Number(pricing.day_rate_long)) * busyMultiplier
      );
    } else {
      const DAY_START = 6;
      const DAY_END = 22;
      const shiftEnd = startHour + per_day_hours; // may exceed 24 for overnight

      const dayOverlapStart = Math.max(startHour, DAY_START);
      const dayOverlapEnd = Math.min(shiftEnd, DAY_END);
      const dayHours = roundQuarter(Math.max(0, dayOverlapEnd - dayOverlapStart));
      const nightHours = roundQuarter(Math.max(0, per_day_hours - dayHours));

      const dayRate =
        per_day_hours < 4
          ? Number(pricing.day_rate_short)
          : per_day_hours <= 6
          ? Number(pricing.day_rate_medium)
          : Number(pricing.day_rate_long);

      const dailyCost = (dayHours * dayRate + nightHours * Number(pricing.night_rate)) * busyMultiplier;
      price = Math.round(dailyCost * coverage_length);
    }
  }

  return { per_day_hours, total_hours, price };
}
```

