/**
 * Authenticate with Monnify and return a bearer access token.
 * Monnify auth flow:
 *   POST /api/v1/auth/login
 *   Authorization: Basic base64(apiKey:secretKey)
 *   -> responseBody.accessToken
 */
async function getMonnifyToken(baseUrl: string, apiKey: string, secretKey: string): Promise<string> {
  const credentials = btoa(`${apiKey}:${secretKey}`);
  console.log('[end-shift] Requesting Monnify token from:', `${baseUrl}/api/v1/auth/login`);
  console.log('[end-shift] Using env vars: MONNIFY_API_KEY, MONNIFY_SECRET_KEY');

  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
  });

  const authData = await authRes.json();
  console.log('[end-shift] Monnify auth HTTP status:', authRes.status);
  console.log('[end-shift] Monnify auth response:', JSON.stringify(authData));

  if (!authRes.ok || !authData.requestSuccessful) {
    const errMsg = authData.responseMessage ?? `Monnify auth error: HTTP ${authRes.status}`;
    throw new Error(`Monnify authentication failed: ${errMsg}`);
  }

  const token = authData.responseBody?.accessToken;
  if (!token) {
    throw new Error('Monnify auth succeeded but no accessToken in response: ' + JSON.stringify(authData));
  }
  return token;
}

async function createMonnifyReservedAccount(
  accountReference: string,
  hospitalName: string,
  requesterName: string,
  requesterEmail: string,
  subaccountCode: string | null
): Promise<MonnifyResult> {
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    throw new Error('Monnify credentials not configured: missing MONNIFY_API_KEY, MONNIFY_SECRET_KEY, or MONNIFY_CONTRACT_CODE');
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';
  console.log(`[end-shift] Monnify env=${monnifyEnv ?? 'live'} baseUrl=${baseUrl}`);

  // Step 1: Get bearer token
  const accessToken = await getMonnifyToken(baseUrl, apiKey, secretKey);
  console.log('[end-shift] Monnify token obtained successfully');

  const body: Record<string, unknown> = {
    accountReference,
    accountName: `FlashLocum / ${hospitalName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: requesterEmail,
    customerName: requesterName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode && subaccountCode.trim()) {
    body.incomeSplitConfig = [{
      subAccountCode: subaccountCode,
      feePercentage: 0,
      splitPercentage: 85,
      feeBearer: false,
    }];
    console.log(`[end-shift] Using incomeSplitConfig with subAccountCode=${subaccountCode}`);
  } else {
    console.log('[end-shift] No subaccount_code found, omitting incomeSplitConfig');
  }

  console.log('[end-shift] Monnify request body:', JSON.stringify({ ...body, accountReference }));

  // Step 2: Create reserved account using bearer token
  const response = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  const data = await response.json();
  console.log('[end-shift] Monnify HTTP status:', response.status);
  console.log('[end-shift] Monnify response:', JSON.stringify(data));

  if (!response.ok || !data.requestSuccessful) {
    throw new Error(`Monnify error (HTTP ${response.status}): ${data.responseMessage ?? JSON.stringify(data)}`);
  }

  const rb = data.responseBody;
  const account = rb.accounts?.[0];

  return {
    accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
    bankName: account?.bankName ?? rb.bankName ?? '',
    accountName: rb.accountName ?? '',
    reference: rb.accountReference ?? accountReference,
  };
}

