```typescript
// supabase/functions/_shared/billing.ts

export type BillingInput = {
  coverageType: string;
  shiftType: string;
  environment: string;
  bookedDurationSeconds: number;
  actualDurationSeconds: number;
  hourlyRateKobo: number;
  nightRateKobo?: number;
  busyMultiplier?: number;
  startHour?: number;
  straight24hFlatKobo?: number;
  straight48hFlatKobo?: number;
  straight72hFlatKobo?: number;
  straightOverageRateKobo?: number;
};

export type BillingResult = {
  billableSeconds: number;
  billableHours: number;
  amountKobo: number;
  amountNaira: number;
  label: string;
  mode: 'continuous' | 'segmented';
};

type RateConfig = {
  day_rate_short: number;
  day_rate_medium: number;
  day_rate_long: number;
  night_rate: number;
  home_care_rate: number;
  busy_multiplier?: number;
};

export function resolveHourlyRateKobo(
  shiftType: string,
  coverageType: string,
  durationHours: number,
  config: RateConfig
): number {
  if (shiftType === 'Home Care' || coverageType === 'Home Care') {
    return Math.round(config.home_care_rate * 100);
  }
  if (coverageType.toLowerCase().includes('night')) {
    return Math.round(config.night_rate * 100);
  }
  if (durationHours < 4) {
    return Math.round(config.day_rate_short * 100);
  } else if (durationHours <= 6) {
    return Math.round(config.day_rate_medium * 100);
  } else {
    return Math.round(config.day_rate_long * 100);
  }
}

const STRAIGHT_COVERAGE_TYPES = ['Straight 24h', 'Straight 48h', 'Straight 72h'];
const MIN_SECONDS = 3600;
const BLOCK_SECONDS = 900;
const GRACE_SECONDS = 900;

export function isStraightCoverage(coverageType: string): boolean {
  return STRAIGHT_COVERAGE_TYPES.some(
    t => coverageType.toLowerCase().includes(t.toLowerCase()) || coverageType === t
  );
}

export function isStraightBooking(
  coverageType: string,
  startTime?: string,
  endTime?: string
): boolean {
  if (isStraightCoverage(coverageType)) return true;
  if (startTime && endTime && startTime.trim() === endTime.trim()) return true;
  return false;
}

export function resolveEffectiveCoverageType(
  coverageType: string,
  coverageLength: number,
  startTime?: string,
  endTime?: string
): string {
  if (isStraightBooking(coverageType, startTime, endTime)) {
    if (coverageLength >= 3) return 'Straight 72h';
    if (coverageLength >= 2) return 'Straight 48h';
    return 'Straight 24h';
  }
  return coverageType;
}

function formatLabel(seconds: number): string {
  const totalMinutes = Math.round(seconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (minutes === 0) return `${hours}hr 00min`;
  return `${hours}hr ${String(minutes).padStart(2, '0')}min`;
}

export function buildCoverageLabel(
  coverageType: string,
  totalHours: number,
  coverageLength: number
): string {
  const h = Math.round(totalHours);
  if (coverageType === 'Straight 24h' || coverageType.toLowerCase().includes('straight 24')) {
    return '24-hour Straight Coverage';
  }
  if (coverageType === 'Straight 48h' || coverageType.toLowerCase().includes('straight 48')) {
    return '48-hour Straight Coverage';
  }
  if (coverageType === 'Straight 72h' || coverageType.toLowerCase().includes('straight 72')) {
    return '72-hour Straight Coverage';
  }
  if (coverageLength > 1) {
    return `${h}-hour Multi-Day Coverage (${coverageLength} days)`;
  }
  return `${h}-hour Single-Day Coverage`;
}

function getEnvironmentMultiplier(shiftType: string, environment: string, busyMultiplier: number = 1.3): number {
  if (shiftType === 'Home Care') return 1.0;
  if (environment === 'Busy') return busyMultiplier;
  return 1.0;
}

function calcSegmented(input: BillingInput): BillingResult {
  const {
    actualDurationSeconds, bookedDurationSeconds, hourlyRateKobo,
    nightRateKobo, shiftType, environment, busyMultiplier = 1.3, startHour,
  } = input;

  const diff = Math.abs(actualDurationSeconds - bookedDurationSeconds);
  let billableSeconds: number;

  if (diff <= GRACE_SECONDS) {
    billableSeconds = bookedDurationSeconds;
  } else {
    billableSeconds = Math.ceil(actualDurationSeconds / BLOCK_SECONDS) * BLOCK_SECONDS;
  }
  billableSeconds = Math.max(billableSeconds, MIN_SECONDS);

  const multiplier = getEnvironmentMultiplier(shiftType, environment, busyMultiplier);
  const billableHours = billableSeconds / 3600;

  let amountKobo: number;

  if (startHour !== undefined && nightRateKobo !== undefined && nightRateKobo > 0 &&
      shiftType !== 'Home Care') {
    const DAY_START = 6;
    const DAY_END = 22;
    const shiftEndHour = startHour + billableHours;
    const dayOverlapStart = Math.max(startHour, DAY_START);
    const dayOverlapEnd = Math.min(shiftEndHour, DAY_END);
    const dayHours = Math.max(0, dayOverlapEnd - dayOverlapStart);
    const nightHours = Math.max(0, billableHours - dayHours);
    amountKobo = Math.round((dayHours * hourlyRateKobo + nightHours * nightRateKobo) * multiplier);
  } else {
    amountKobo = Math.round(billableHours * hourlyRateKobo * multiplier);
  }

  return {
    billableSeconds,
    billableHours,
    amountKobo,
    amountNaira: amountKobo / 100,
    label: formatLabel(billableSeconds),
    mode: 'segmented',
  };
}

function calcContinuous(input: BillingInput): BillingResult {
  const {
    actualDurationSeconds,
    bookedDurationSeconds,
    hourlyRateKobo,
    shiftType,
    environment,
    straight24hFlatKobo = 3600000,
    straight48hFlatKobo = 7200000,
    straight72hFlatKobo = 10800000,
    straightOverageRateKobo = 150000,
  } = input;

  const actualHours = actualDurationSeconds / 3600;
  const multiplier = getEnvironmentMultiplier(shiftType, environment, input.busyMultiplier ?? 1.3);
  const bookedHours = bookedDurationSeconds / 3600;

  let flatKobo: number;
  let lowerBound: number;
  let upperBound: number;

  if (bookedHours <= 26) {
    flatKobo = straight24hFlatKobo;
    lowerBound = 22;
    upperBound = 25;
  } else if (bookedHours <= 50) {
    flatKobo = straight48hFlatKobo;
    lowerBound = 46;
    upperBound = 49;
  } else {
    flatKobo = straight72hFlatKobo;
    lowerBound = 70;
    upperBound = 73;
  }

  let amountKobo: number;
  let billableSeconds: number;

  if (actualHours <= upperBound) {
    amountKobo = Math.round(flatKobo * multiplier);
    billableSeconds = lowerBound * 3600;
  } else {
    const overageHours = actualHours - upperBound;
    const overageKobo = overageHours * straightOverageRateKobo;
    amountKobo = Math.round((flatKobo + overageKobo) * multiplier);
    billableSeconds = actualDurationSeconds;
  }

  const billableHours = billableSeconds / 3600;

  return {
    billableSeconds,
    billableHours,
    amountKobo,
    amountNaira: amountKobo / 100,
    label: formatLabel(billableSeconds),
    mode: 'continuous',
  };
}

export function calculateBill(input: BillingInput): BillingResult {
  if (isStraightCoverage(input.coverageType)) {
    return calcContinuous(input);
  }
  return calcSegmented(input);
}
