## `end-shift` (version 18) — `index.ts`

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import {
  fetchPricingRules,
  calcStandardNaira,
  calcStraightNaira,
  splitNaira,
  resolveHourlyRate,
  isStraightCoverage,
  resolveEffectiveCoverageType,
} from './_shared/billing.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[end-shift] Broadcast OK to ${channel} event=${event}`);
  }
}

type DayLog = {
  day: number;
  started_at: string;
  paused_at: string | null;
  duration_seconds: number;
  cost?: number;
  day_cost_kobo?: number;
};

type MonnifyResult = {
  accountNumber: string;
  bankName: string;
  accountName: string;
  reference: string;
};

async function getMonnifyToken(baseUrl: string, apiKey: string, secretKey: string): Promise<string> {
  const credentials = btoa(`${apiKey}:${secretKey}`);
  console.log('[end-shift] Requesting Monnify token from:', `${baseUrl}/api/v1/auth/login`);

  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
  });

  const authData = await authRes.json();
  console.log('[end-shift] Monnify auth HTTP status:', authRes.status);
  console.log('[end-shift] Monnify auth response:', JSON.stringify(authData));

  if (!authRes.ok || !authData.requestSuccessful) {
    const errMsg = authData.responseMessage ?? `Monnify auth error: HTTP ${authRes.status}`;
    throw new Error(`Monnify authentication failed: ${errMsg}`);
  }

  const token = authData.responseBody?.accessToken;
  if (!token) {
    throw new Error('Monnify auth succeeded but no accessToken in response: ' + JSON.stringify(authData));
  }
  return token;
}

// GET-before-POST: reuse existing reserved account or create a new one
async function getMonnifyReservedAccount(
  accountReference: string,
  hospitalName: string,
  requesterName: string,
  requesterEmail: string,
  subaccountCode: string | null,
  doctorNaira: number,
  platformNaira: number,
  baseUrl: string,
  accessToken: string,
  contractCode: string
): Promise<MonnifyResult> {
  // Step 1: Try to GET existing account
  const getRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts/${accountReference}`, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
  });
  const getData = await getRes.json();
  console.log('[end-shift] Monnify GET status:', getRes.status, JSON.stringify(getData));

  if (getRes.ok && getData.requestSuccessful) {
    // Account already exists — reuse it
    const rb = getData.responseBody;
    const account = rb.accounts?.[0];
    console.log('[end-shift] Reusing existing Monnify reserved account:', accountReference);
    return {
      accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
      bankName: account?.bankName ?? rb.bankName ?? '',
      accountName: rb.accountName ?? '',
      reference: rb.accountReference ?? accountReference,
    };
  }

  // Step 2: Account doesn't exist — create it
  const body: Record<string, unknown> = {
    accountReference,
    accountName: `FlashLocum / ${hospitalName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: requesterEmail,
    customerName: requesterName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode && subaccountCode.trim()) {
    const totalNaira = doctorNaira + platformNaira;
    const doctorSplitPct = totalNaira > 0 ? (doctorNaira / totalNaira) * 100 : 85;
    body.incomeSplitConfig = [{
      subAccountCode: subaccountCode,
      feePercentage: 0,
      splitPercentage: Math.round(doctorSplitPct * 100) / 100,
      feeBearer: false,
    }];
    console.log(`[end-shift] incomeSplitConfig: subAccountCode=${subaccountCode} doctorNaira=₦${doctorNaira} platformNaira=₦${platformNaira} splitPct=${((doctorNaira / (doctorNaira + platformNaira)) * 100).toFixed(2)}%`);
  } else {
    console.log('[end-shift] No subaccount_code found, omitting incomeSplitConfig');
  }

  console.log('[end-shift] Monnify POST request body:', JSON.stringify({ ...body, accountReference }));

  const postRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const postData = await postRes.json();
  console.log('[end-shift] Monnify POST status:', postRes.status, JSON.stringify(postData));

  if (!postRes.ok || !postData.requestSuccessful) {
    throw new Error(`Monnify error (HTTP ${postRes.status}): ${postData.responseMessage ?? JSON.stringify(postData)}`);
  }

  const rb = postData.responseBody;
  const account = rb.accounts?.[0];
  return {
    accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
    bankName: account?.bankName ?? rb.bankName ?? '',
    accountName: rb.accountName ?? '',
    reference: rb.accountReference ?? accountReference,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(
      JSON.stringify({ error: 'Method not allowed' }),
      { status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) {
    return new Response(
      JSON.stringify({ error: 'No auth' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) {
    return new Response(
      JSON.stringify({ error: 'Unauthorized' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(
      JSON.stringify({ error: 'Invalid JSON body' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(
      JSON.stringify({ error: 'session_id required' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const { data: session, error: sessionError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (sessionError || !session) {
    console.error('[end-shift] ERROR: Session not found', { session_id, sessionError });
    return new Response(
      JSON.stringify({ error: 'Session not found' }),
      { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  if (session.requester_id !== user.id) {
    return new Response(
      JSON.stringify({ error: 'Forbidden: only the requester can end a shift' }),
      { status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  if (!['active', 'paused'].includes(session.status)) {
    return new Response(
      JSON.stringify({ error: `Cannot end a shift with status: ${session.status}` }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  let rules;
  try {
    rules = await fetchPricingRules(supabaseAdmin);
  } catch (e: any) {
    console.error('[end-shift] fetchPricingRules failed:', e.message);
    return new Response(
      JSON.stringify({ error: `Pricing rules unavailable: ${e.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const currentDay = session.current_day ?? 1;

  const coverageType = session.coverage_type ?? 'Standard';
  const coverageLength = session.coverage_length ?? 1;
  const perDayHours = Number(session.per_day_hours ?? 8);
  const totalBookedHours = perDayHours * coverageLength;

  const effectiveCoverageType = resolveEffectiveCoverageType(
    coverageType,
    coverageLength,
    session.shift_start ? new Date(session.shift_start).toTimeString().slice(0, 5) : undefined,
    session.shift_end ? new Date(session.shift_end).toTimeString().slice(0, 5) : undefined
  );

  const isStraight = isStraightCoverage(effectiveCoverageType) ||
    totalBookedHours === 24 || totalBookedHours === 48 || totalBookedHours === 72;

  console.log(`[end-shift] session=${session_id} coverageType=${coverageType} effectiveCoverageType=${effectiveCoverageType} isStraight=${isStraight} perDayHours=${perDayHours} coverageLength=${coverageLength} totalBookedHours=${totalBookedHours}`);

  let finalDayLogs: DayLog[] = Array.isArray(session.day_logs) ? [...session.day_logs] : [];
  let finalDayCostNaira: number;

  if (isStraight) {
    const sessionStart = session.started_at ? new Date(session.started_at) : now;
    const totalElapsedSeconds = Math.floor((now.getTime() - sessionStart.getTime()) / 1000);
    const straightHours = (totalBookedHours === 48 ? 48 : totalBookedHours === 72 ? 72 : 24) as 24 | 48 | 72;

    finalDayCostNaira = calcStraightNaira({
      actualSeconds: totalElapsedSeconds,
      bookedHours: straightHours,
      rules,
    });
    console.log(`[end-shift] STRAIGHT billing: straightHours=${straightHours} totalElapsedSeconds=${totalElapsedSeconds} -> ₦${finalDayCostNaira}`);

    finalDayLogs.push({
      day: currentDay,
      started_at: sessionStart.toISOString(),
      paused_at: nowIso,
      duration_seconds: totalElapsedSeconds,
      cost: finalDayCostNaira,
    });

  } else {
    let currentSegmentSeconds = 0;
    if (session.status === 'active' && session.started_at) {
      const segmentStart = new Date(session.started_at);
      currentSegmentSeconds = Math.floor((now.getTime() - segmentStart.getTime()) / 1000);
    }

    const hourlyRateNaira = resolveHourlyRate(session, rules);
    finalDayCostNaira = currentSegmentSeconds > 0
      ? calcStandardNaira({
          actualSeconds: currentSegmentSeconds,
          bookedHours: perDayHours,
          hourlyRateNaira,
          rules,
        })
      : 0;

    console.log(`[end-shift] STANDARD billing: perDayHours=${perDayHours} hourlyRateNaira=${hourlyRateNaira} currentSegmentSeconds=${currentSegmentSeconds} -> ₦${finalDayCostNaira}`);

    if (currentSegmentSeconds > 0 && session.started_at) {
      finalDayLogs.push({
        day: currentDay,
        started_at: session.started_at,
        paused_at: nowIso,
        duration_seconds: currentSegmentSeconds,
        cost: finalDayCostNaira,
      });
    }
  }

  let completedDaysCostNaira = 0;
  for (const log of finalDayLogs) {
    if (log.day !== currentDay && log.cost != null) {
      completedDaysCostNaira += Number(log.cost);
    }
  }

  const totalNaira = completedDaysCostNaira + finalDayCostNaira;

  console.log(`[end-shift] TOTAL: completedDays=₦${completedDaysCostNaira} + finalDay=₦${finalDayCostNaira} = ₦${totalNaira}`);

  const { platformNaira, doctorNaira } = splitNaira(totalNaira, rules);
  console.log(`[end-shift] Split: platform=₦${platformNaira} doctor=₦${doctorNaira}`);

  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code')
    .eq('id', session.doctor_id)
    .maybeSingle();

  const subaccountCode = doctorProfile?.subaccount_code ?? null;

  // Customer-scoped account reference — same for every session by the same requester
  const requesterId = session.requester_id as string;
  const accountReference = `FL-${requesterId.replace(/-/g, '').slice(0, 20)}`;
  console.log(`[end-shift] accountReference=${accountReference} (requester-scoped, requester_id=${requesterId})`);

  // Fetch requester info for Monnify account name
  const { data: requesterProfile } = await supabaseAdmin
    .from('profiles')
    .select('first_name, last_name')
    .eq('id', user.id)
    .single();

  const { data: authUserData } = await supabaseAdmin.auth.admin.getUserById(user.id);
  const requesterEmail = authUserData?.user?.email ?? 'noreply@flashlocum.com';
  const requesterName = requesterProfile
    ? `${requesterProfile.first_name ?? ''} ${requesterProfile.last_name ?? ''}`.trim()
    : 'FlashLocum User';

  // Monnify credentials
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    return new Response(
      JSON.stringify({ error: 'Monnify credentials not configured: missing MONNIFY_API_KEY, MONNIFY_SECRET_KEY, or MONNIFY_CONTRACT_CODE' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';
  console.log(`[end-shift] Monnify env=${monnifyEnv ?? 'live'} baseUrl=${baseUrl}`);

  let accessToken: string;
  try {
    accessToken = await getMonnifyToken(baseUrl, apiKey, secretKey);
    console.log('[end-shift] Monnify token obtained successfully');
  } catch (monnifyErr: any) {
    console.error('[end-shift] Monnify auth error:', monnifyErr.message);
    return new Response(
      JSON.stringify({ error: `Payment setup failed: ${monnifyErr.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  // GET-before-POST pattern — customer-scoped reference guarantees no 422
  let monnifyData: MonnifyResult;
  try {
    monnifyData = await getMonnifyReservedAccount(
      accountReference,
      session.hospital_name ?? 'Hospital',
      requesterName,
      requesterEmail,
      subaccountCode,
      doctorNaira,
      platformNaira,
      baseUrl,
      accessToken,
      contractCode
    );
    console.log('[end-shift] Monnify reserved account ready:', JSON.stringify(monnifyData));
  } catch (monnifyErr: any) {
    console.error('[end-shift] Monnify error:', monnifyErr.message);
    return new Response(
      JSON.stringify({ error: `Payment setup failed: ${monnifyErr.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const monnifyFields = {
    monnify_account_reference: monnifyData.reference,
    monnify_account_number: monnifyData.accountNumber,
    monnify_bank_name: monnifyData.bankName,
    monnify_account_name: monnifyData.accountName,
  };

  const paymentDeadline = new Date(now.getTime() + 15 * 60 * 1000);
  const expiryAt = paymentDeadline.toISOString();

  const updatePayload: Record<string, unknown> = {
    status: 'payment_pending',
    ended_at: nowIso,
    day_logs: finalDayLogs,
    total_cost: totalNaira,
    price: totalNaira,
    payment_initiated_at: nowIso,
    payment_deadline_at: expiryAt,
    payment_status: 'pending',
    ...monnifyFields,
  };

  const { data: updated, error: updateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update(updatePayload)
    .eq('id', session_id)
    .select()
    .single();

  if (updateError) {
    console.error('[end-shift] ERROR: DB update failed:', updateError);
    return new Response(
      JSON.stringify({ error: `Database update failed: ${updateError.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  // Expire any existing pending intents before inserting new one
  await supabaseAdmin
    .from('payment_intents')
    .update({ status: 'expired', updated_at: new Date().toISOString() })
    .eq('session_id', session_id)
    .eq('status', 'pending');

  const { data: paymentIntent, error: piError } = await supabaseAdmin
    .from('payment_intents')
    .insert({
      session_id: session_id,
      amount_naira: totalNaira,
      monnify_account_number: monnifyData.accountNumber,
      monnify_bank_name: monnifyData.bankName,
      monnify_account_reference: monnifyData.reference,
      status: 'pending',
      expiry_at: expiryAt,
    })
    .select()
    .single();

  if (piError) {
    console.error('[end-shift] WARNING: Failed to insert payment_intent:', piError);
  }

  const broadcastPayload = {
    session_id,
    status: 'payment_pending',
    price: totalNaira,
    total_naira: totalNaira,
    platform_naira: platformNaira,
    doctor_naira: doctorNaira,
    monnify_account_number: monnifyFields.monnify_account_number,
    monnify_bank_name: monnifyFields.monnify_bank_name,
    monnify_account_name: monnifyFields.monnify_account_name,
    monnify_account_reference: monnifyFields.monnify_account_reference,
    payment_deadline_at: expiryAt,
  };

  await Promise.all([
    broadcastToChannel(`session:${session_id}`, 'SHIFT_ENDED', broadcastPayload),
    broadcastToChannel(`doctor:${session.doctor_id}`, 'SHIFT_ENDED', broadcastPayload),
  ]);

  return new Response(JSON.stringify({
    success: true,
    session: updated,
    total_naira: totalNaira,
    platform_naira: platformNaira,
    doctor_naira: doctorNaira,
    account_number: monnifyFields.monnify_account_number,
    bank_name: monnifyFields.monnify_bank_name,
    account_name: monnifyFields.monnify_account_name,
    payment_deadline_at: expiryAt,
    payment: paymentIntent ? {
      id: paymentIntent.id,
      amount_naira: totalNaira,
      account_number: monnifyData.accountNumber,
      bank_name: monnifyData.bankName,
      account_reference: monnifyData.reference,
      expiry_at: expiryAt,
    } : null,
  }), {
    status: 200,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
