## `refresh-payment` (version 3) — `index.ts`

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import {
  fetchPricingRules,
  splitNaira,
} from './_shared/billing.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`[refresh-payment] Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[refresh-payment] Broadcast OK to ${channel} event=${event}`);
  }
}

async function getMonnifyToken(baseUrl: string, apiKey: string, secretKey: string): Promise<string> {
  const credentials = btoa(`${apiKey}:${secretKey}`);
  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
  });
  const authData = await authRes.json();
  if (!authRes.ok || !authData.requestSuccessful) {
    throw new Error(`Monnify authentication failed: ${authData.responseMessage ?? `HTTP ${authRes.status}`}`);
  }
  const token = authData.responseBody?.accessToken;
  if (!token) throw new Error('Monnify auth succeeded but no accessToken in response');
  return token;
}

type MonnifyResult = {
  accountNumber: string;
  bankName: string;
  accountName: string;
  reference: string;
};

// GET-before-POST: reuse existing reserved account or create a new one
async function getMonnifyReservedAccount(
  accountReference: string,
  hospitalName: string,
  requesterName: string,
  requesterEmail: string,
  subaccountCode: string | null,
  doctorNaira: number,
  platformNaira: number,
  baseUrl: string,
  accessToken: string,
  contractCode: string
): Promise<MonnifyResult> {
  // Step 1: Try to GET existing account
  const getRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts/${accountReference}`, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
  });
  const getData = await getRes.json();
  console.log('[refresh-payment] Monnify GET status:', getRes.status, JSON.stringify(getData));

  if (getRes.ok && getData.requestSuccessful) {
    // Account already exists — reuse it
    const rb = getData.responseBody;
    const account = rb.accounts?.[0];
    console.log('[refresh-payment] Reusing existing Monnify reserved account:', accountReference);
    return {
      accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
      bankName: account?.bankName ?? rb.bankName ?? '',
      accountName: rb.accountName ?? '',
      reference: rb.accountReference ?? accountReference,
    };
  }

  // Step 2: Account doesn't exist — create it
  const body: Record<string, unknown> = {
    accountReference,
    accountName: `FlashLocum / ${hospitalName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: requesterEmail,
    customerName: requesterName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode && subaccountCode.trim()) {
    const totalNaira = doctorNaira + platformNaira;
    const doctorSplitPct = totalNaira > 0 ? (doctorNaira / totalNaira) * 100 : 85;
    body.incomeSplitConfig = [{
      subAccountCode: subaccountCode,
      feePercentage: 0,
      splitPercentage: Math.round(doctorSplitPct * 100) / 100,
      feeBearer: false,
    }];
    console.log(`[refresh-payment] incomeSplitConfig: subAccountCode=${subaccountCode} splitPct=${doctorSplitPct.toFixed(2)}%`);
  }

  console.log('[refresh-payment] Monnify POST request body:', JSON.stringify({ ...body, accountReference }));

  const postRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });
  const postData = await postRes.json();
  console.log('[refresh-payment] Monnify POST status:', postRes.status, JSON.stringify(postData));

  if (!postRes.ok || !postData.requestSuccessful) {
    throw new Error(`Monnify error (HTTP ${postRes.status}): ${postData.responseMessage ?? JSON.stringify(postData)}`);
  }

  const rb = postData.responseBody;
  const account = rb.accounts?.[0];
  return {
    accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
    bankName: account?.bankName ?? rb.bankName ?? '',
    accountName: rb.accountName ?? '',
    reference: rb.accountReference ?? accountReference,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: corsHeaders });

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) return new Response(JSON.stringify({ error: 'No auth' }), { status: 401, headers: corsHeaders });

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: corsHeaders });
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), { status: 400, headers: corsHeaders });
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(JSON.stringify({ error: 'session_id required' }), { status: 400, headers: corsHeaders });
  }

  // Fetch session — must be owned by this requester
  const { data: session, error: sessionError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (sessionError || !session) {
    return new Response(JSON.stringify({ error: 'Session not found' }), { status: 404, headers: corsHeaders });
  }

  if (session.requester_id !== user.id) {
    return new Response(JSON.stringify({ error: 'Forbidden' }), { status: 403, headers: corsHeaders });
  }

  // Must be payment_pending (shift ended) and not already paid
  if (!['payment_pending', 'completed'].includes(session.status)) {
    return new Response(JSON.stringify({ error: `Cannot refresh payment for session with status: ${session.status}` }), { status: 400, headers: corsHeaders });
  }

  if (session.status === 'requester_paid') {
    return new Response(JSON.stringify({ error: 'Session already paid' }), { status: 400, headers: corsHeaders });
  }

  // Expire all existing pending payment_intents for this session
  const { error: expireError } = await supabaseAdmin
    .from('payment_intents')
    .update({ status: 'expired', updated_at: new Date().toISOString() })
    .eq('session_id', session_id)
    .eq('status', 'pending');

  if (expireError) {
    console.error('[refresh-payment] Failed to expire old payment_intents:', expireError);
  }

  // Use total_cost from DB as authoritative amount
  const totalNaira = Number(session.total_cost ?? 0);

  // Fetch pricing rules for split
  const rules = await fetchPricingRules(supabaseAdmin);
  const { platformNaira, doctorNaira } = splitNaira(totalNaira, rules);

  // Fetch doctor subaccount code
  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code')
    .eq('id', session.doctor_id)
    .maybeSingle();

  const subaccountCode = doctorProfile?.subaccount_code ?? null;

  // Monnify credentials
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    return new Response(JSON.stringify({ error: 'Monnify credentials not configured' }), { status: 500, headers: corsHeaders });
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';

  let accessToken: string;
  try {
    accessToken = await getMonnifyToken(baseUrl, apiKey, secretKey);
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Monnify auth error';
    console.error('[refresh-payment] Monnify auth failed:', msg);
    return new Response(JSON.stringify({ error: `Monnify auth failed: ${msg}` }), { status: 500, headers: corsHeaders });
  }

  // Fetch requester info for Monnify account name
  const { data: requesterProfile } = await supabaseAdmin
    .from('profiles')
    .select('first_name, last_name')
    .eq('id', user.id)
    .single();

  const { data: authUserData } = await supabaseAdmin.auth.admin.getUserById(user.id);
  const requesterEmail = authUserData?.user?.email ?? 'noreply@flashlocum.com';
  const requesterName = requesterProfile
    ? `${requesterProfile.first_name ?? ''} ${requesterProfile.last_name ?? ''}`.trim()
    : 'FlashLocum User';

  // Customer-scoped account reference — same for every session by the same requester
  const requesterId = session.requester_id as string;
  const accountReference = `FL-${requesterId.replace(/-/g, '').slice(0, 20)}`;
  console.log(`[refresh-payment] accountReference=${accountReference} (requester-scoped, requester_id=${requesterId})`);

  // GET-before-POST pattern — customer-scoped reference guarantees no 422
  let monnifyResult: MonnifyResult;
  try {
    monnifyResult = await getMonnifyReservedAccount(
      accountReference,
      session.hospital_name ?? 'Hospital',
      requesterName,
      requesterEmail,
      subaccountCode,
      doctorNaira,
      platformNaira,
      baseUrl,
      accessToken,
      contractCode
    );
    console.log('[refresh-payment] Monnify reserved account ready:', JSON.stringify(monnifyResult));
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Monnify error';
    console.error('[refresh-payment] Monnify error:', msg);
    return new Response(JSON.stringify({ error: `Monnify error: ${msg}` }), { status: 500, headers: corsHeaders });
  }

  const accountNumber = monnifyResult.accountNumber;
  const bankName = monnifyResult.bankName;
  const newAccountReference = monnifyResult.reference;

  const expiryAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();

  // Insert new payment_intent
  const { data: paymentIntent, error: piError } = await supabaseAdmin
    .from('payment_intents')
    .insert({
      session_id: session_id,
      amount_naira: totalNaira,
      monnify_account_number: accountNumber,
      monnify_bank_name: bankName,
      monnify_account_reference: newAccountReference,
      status: 'pending',
      expiry_at: expiryAt,
    })
    .select()
    .single();

  if (piError || !paymentIntent) {
    console.error('[refresh-payment] Failed to insert payment_intent:', piError);
    return new Response(JSON.stringify({ error: 'Failed to create payment intent' }), { status: 500, headers: corsHeaders });
  }

  // Update coverage_sessions with new Monnify account details and new deadline
  await supabaseAdmin
    .from('coverage_sessions')
    .update({
      monnify_account_reference: newAccountReference,
      monnify_account_number: accountNumber,
      monnify_bank_name: bankName,
      payment_deadline_at: expiryAt,
      payment_initiated_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    })
    .eq('id', session_id);

  const paymentPayload = {
    id: paymentIntent.id,
    amount_naira: totalNaira,
    account_number: accountNumber,
    bank_name: bankName,
    account_reference: newAccountReference,
    expiry_at: expiryAt,
  };

  // Broadcast payment_refreshed on session channel
  await broadcastToChannel(`session:${session_id}`, 'payment_refreshed', { payment: paymentPayload });

  return new Response(JSON.stringify({
    success: true,
    payment: paymentPayload,
  }), {
    status: 200,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
