## `start-shift` — `index.ts` (v7)

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[start-shift] Broadcast OK to ${channel} event=${event}`);
  }
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405, headers: corsHeaders });
  }

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: req.headers.get('Authorization')! } } }
  );

  const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(JSON.stringify({ error: 'Missing field: session_id' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { data: session, error: fetchError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (fetchError || !session) {
    return new Response(JSON.stringify({ error: 'Session not found' }), {
      status: 404,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Requester-only: verify caller is the requester
  if (session.requester_id !== user.id) {
    return new Response(JSON.stringify({ error: 'Forbidden: only the requester can start a shift' }), {
      status: 403,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Only allow starting from 'upcoming' status
  if (session.status !== 'upcoming') {
    return new Response(JSON.stringify({ error: `Cannot start a shift with status: ${session.status}` }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const now = new Date().toISOString();

  // Initialize day_logs with day 1 entry and reset current_day to 1
  const initialDayLogs = [{ day: 1, started_at: now, paused_at: null, duration_seconds: 0 }];

  const { data: updated, error: updateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update({
      status: 'active',
      started_at: now,
      current_day: 1,
      day_logs: initialDayLogs,
      updated_at: now,
    })
    .eq('id', session_id)
    .select()
    .single();

  if (updateError) {
    return new Response(JSON.stringify({ error: updateError.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Broadcast SHIFT_STARTED to session channel and doctor's personal channel
  const shiftPayload = { session: updated };
  await Promise.all([
    broadcastToChannel(`session:${session_id}`, 'SHIFT_STARTED', shiftPayload),
    broadcastToChannel(`doctor:${session.doctor_id}`, 'SHIFT_STARTED', shiftPayload),
  ]);

  return new Response(JSON.stringify({ session: updated }), {
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
