    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(JSON.stringify({ error: 'Missing field: session_id' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Fetch current session
  const { data: session, error: fetchError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (fetchError || !session) {
    return new Response(JSON.stringify({ error: 'Session not found' }), {
      status: 404,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (session.requester_id !== user.id) {
    return new Response(JSON.stringify({ error: 'Forbidden: only the requester can resume a shift' }), {
      status: 403,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Only accept 'paused' status
  if (session.status !== 'paused') {
    return new Response(JSON.stringify({ error: `Cannot resume a shift with status: ${session.status}` }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const now = new Date().toISOString();
  const currentDay = session.current_day ?? 1;

  // Append a new day log entry for the current day (already incremented by pause-shift)
  const existingDayLogs: Array<{ day: number; started_at: string; paused_at: string | null; duration_seconds: number }> = session.day_logs ?? [];
  const newDayLog = { day: currentDay, started_at: now, paused_at: null, duration_seconds: 0 };
  const updatedDayLogs = [...existingDayLogs, newDayLog];

  // Set status to 'active', clear paused_at
  const { data: updated, error: updateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update({
      status: 'active',
      paused_at: null,
      day_logs: updatedDayLogs,
      updated_at: now,
    })
    .eq('id', session_id)
    .select()
    .single();

  if (updateError) {
    return new Response(JSON.stringify({ error: updateError.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const shiftPayload = { session: updated };
  await broadcastToChannel(`session:${session_id}`, 'SHIFT_RESUMED', shiftPayload);

  return new Response(JSON.stringify({ session: updated }), {
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
