## 1. `end-shift` (version 20)

### `index.ts`
```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import {
  fetchPricingRules,
  calcStandardNaira,
  calcStraightNaira,
  splitNaira,
  resolveHourlyRate,
  isStraightCoverage,
  resolveEffectiveCoverageType,
} from './_shared/billing.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[end-shift] Broadcast OK to ${channel} event=${event}`);
  }
}

type DayLog = {
  day: number;
  started_at: string;
  paused_at: string | null;
  duration_seconds: number;
  cost?: number;
  day_cost_kobo?: number;
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') {
    return new Response(
      JSON.stringify({ error: 'Method not allowed' }),
      { status: 405, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) {
    return new Response(
      JSON.stringify({ error: 'No auth' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) {
    return new Response(
      JSON.stringify({ error: 'Unauthorized' }),
      { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(
      JSON.stringify({ error: 'Invalid JSON body' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(
      JSON.stringify({ error: 'session_id required' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const { data: session, error: sessionError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (sessionError || !session) {
    console.error('[end-shift] ERROR: Session not found', { session_id, sessionError });
    return new Response(
      JSON.stringify({ error: 'Session not found' }),
      { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  if (session.requester_id !== user.id) {
    return new Response(
      JSON.stringify({ error: 'Forbidden: only the requester can end a shift' }),
      { status: 403, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  if (!['active', 'paused'].includes(session.status)) {
    return new Response(
      JSON.stringify({ error: `Cannot end a shift with status: ${session.status}` }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  let rules;
  try {
    rules = await fetchPricingRules(supabaseAdmin);
  } catch (e: any) {
    console.error('[end-shift] fetchPricingRules failed:', e.message);
    return new Response(
      JSON.stringify({ error: `Pricing rules unavailable: ${e.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const now = new Date();
  const nowIso = now.toISOString();
  const currentDay = session.current_day ?? 1;

  const coverageType = session.coverage_type ?? 'Standard';
  const coverageLength = session.coverage_length ?? 1;
  const perDayHours = Number(session.per_day_hours ?? 8);
  const totalBookedHours = perDayHours * coverageLength;

  const effectiveCoverageType = resolveEffectiveCoverageType(
    coverageType,
    coverageLength,
    session.shift_start ? new Date(session.shift_start).toTimeString().slice(0, 5) : undefined,
    session.shift_end ? new Date(session.shift_end).toTimeString().slice(0, 5) : undefined
  );

  const isStraight = isStraightCoverage(effectiveCoverageType) ||
    totalBookedHours === 24 || totalBookedHours === 48 || totalBookedHours === 72;

  console.log(`[end-shift] session=${session_id} coverageType=${coverageType} effectiveCoverageType=${effectiveCoverageType} isStraight=${isStraight} perDayHours=${perDayHours} coverageLength=${coverageLength} totalBookedHours=${totalBookedHours}`);

  let finalDayLogs: DayLog[] = Array.isArray(session.day_logs) ? [...session.day_logs] : [];
  let finalDayCostNaira: number;

  if (isStraight) {
    const sessionStart = session.started_at ? new Date(session.started_at) : now;
    const totalElapsedSeconds = Math.floor((now.getTime() - sessionStart.getTime()) / 1000);
    const straightHours = (totalBookedHours === 48 ? 48 : totalBookedHours === 72 ? 72 : 24) as 24 | 48 | 72;

    finalDayCostNaira = calcStraightNaira({
      actualSeconds: totalElapsedSeconds,
      bookedHours: straightHours,
      rules,
    });
    console.log(`[end-shift] STRAIGHT billing: straightHours=${straightHours} totalElapsedSeconds=${totalElapsedSeconds} -> ₦${finalDayCostNaira}`);

    finalDayLogs.push({
      day: currentDay,
      started_at: sessionStart.toISOString(),
      paused_at: nowIso,
      duration_seconds: totalElapsedSeconds,
      cost: finalDayCostNaira,
    });

  } else {
    let currentSegmentSeconds = 0;
    if (session.status === 'active' && session.started_at) {
      const segmentStart = new Date(session.started_at);
      currentSegmentSeconds = Math.floor((now.getTime() - segmentStart.getTime()) / 1000);
    }

    const hourlyRateNaira = resolveHourlyRate(session, rules);
    finalDayCostNaira = currentSegmentSeconds > 0
      ? calcStandardNaira({
          actualSeconds: currentSegmentSeconds,
          bookedHours: perDayHours,
          hourlyRateNaira,
          rules,
        })
      : 0;

    console.log(`[end-shift] STANDARD billing: perDayHours=${perDayHours} hourlyRateNaira=${hourlyRateNaira} currentSegmentSeconds=${currentSegmentSeconds} -> ₦${finalDayCostNaira}`);

    if (currentSegmentSeconds > 0 && session.started_at) {
      finalDayLogs.push({
        day: currentDay,
        started_at: session.started_at,
        paused_at: nowIso,
        duration_seconds: currentSegmentSeconds,
        cost: finalDayCostNaira,
      });
    }
  }

  let completedDaysCostNaira = 0;
  for (const log of finalDayLogs) {
    if (log.day !== currentDay && log.cost != null) {
      completedDaysCostNaira += Number(log.cost);
    }
  }

  const totalNaira = completedDaysCostNaira + finalDayCostNaira;

  console.log(`[end-shift] TOTAL: completedDays=₦${completedDaysCostNaira} + finalDay=₦${finalDayCostNaira} = ₦${totalNaira}`);

  const { platformNaira, doctorNaira } = splitNaira(totalNaira, rules);
  console.log(`[end-shift] Split: platform=₦${platformNaira} doctor=₦${doctorNaira}`);

  // Read doctor's stored reserved account from doctor_profiles
  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code, reserved_account_number, reserved_account_bank, reserved_account_reference, reserved_account_name')
    .eq('id', session.doctor_id)
    .maybeSingle();

  let monnifyAccountNumber = doctorProfile?.reserved_account_number ?? '';
  let monnifyBankName = doctorProfile?.reserved_account_bank ?? '';
  let monnifyAccountReference = doctorProfile?.reserved_account_reference ?? '';
  let monnifyAccountName = doctorProfile?.reserved_account_name ?? '';

  // Fallback: provision inline if not yet stored (existing doctors)
  if (!monnifyAccountNumber) {
    console.log('[end-shift] No stored reserved account for doctor, provisioning inline...');
    try {
      const provisionRes = await fetch(
        `${Deno.env.get('SUPABASE_URL')}/functions/v1/provision-reserved-account`,
        {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ doctor_id: session.doctor_id }),
        }
      );
      const provisionData = await provisionRes.json();
      if (provisionRes.ok && provisionData.account_number) {
        monnifyAccountNumber = provisionData.account_number;
        monnifyBankName = provisionData.bank_name;
        monnifyAccountReference = provisionData.account_reference;
        monnifyAccountName = provisionData.account_name ?? '';
        console.log('[end-shift] Inline provisioning succeeded:', monnifyAccountNumber);
      } else {
        throw new Error(provisionData.error ?? 'Provisioning failed');
      }
    } catch (provErr: any) {
      console.error('[end-shift] Inline provisioning failed:', provErr.message);
      return new Response(
        JSON.stringify({ error: `Payment setup failed: ${provErr.message}` }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
  }

  const monnifyFields = {
    monnify_account_reference: monnifyAccountReference,
    monnify_account_number: monnifyAccountNumber,
    monnify_bank_name: monnifyBankName,
    monnify_account_name: monnifyAccountName,
  };

  const paymentDeadline = new Date(now.getTime() + 15 * 60 * 1000);
  const expiryAt = paymentDeadline.toISOString();

  const updatePayload: Record<string, unknown> = {
    status: 'payment_pending',
    ended_at: nowIso,
    day_logs: finalDayLogs,
    total_cost: totalNaira,
    price: totalNaira,
    payment_initiated_at: nowIso,
    payment_deadline_at: expiryAt,
    payment_status: 'pending',
    ...monnifyFields,
  };

  const { data: updated, error: updateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update(updatePayload)
    .eq('id', session_id)
    .select()
    .single();

  if (updateError) {
    console.error('[end-shift] ERROR: DB update failed:', updateError);
    return new Response(
      JSON.stringify({ error: `Database update failed: ${updateError.message}` }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  // Expire any existing pending intents before inserting new one
  await supabaseAdmin
    .from('payment_intents')
    .update({ status: 'expired', updated_at: new Date().toISOString() })
    .eq('session_id', session_id)
    .eq('status', 'pending');

  const { data: paymentIntent, error: piError } = await supabaseAdmin
    .from('payment_intents')
    .insert({
      session_id: session_id,
      amount_naira: totalNaira,
      monnify_account_number: monnifyAccountNumber,
      monnify_bank_name: monnifyBankName,
      monnify_account_reference: monnifyAccountReference,
      status: 'pending',
      expiry_at: expiryAt,
    })
    .select()
    .single();

  if (piError) {
    console.error('[end-shift] WARNING: Failed to insert payment_intent:', piError);
  }

  const broadcastPayload = {
    session_id,
    status: 'payment_pending',
    price: totalNaira,
    total_naira: totalNaira,
    platform_naira: platformNaira,
    doctor_naira: doctorNaira,
    monnify_account_number: monnifyFields.monnify_account_number,
    monnify_bank_name: monnifyFields.monnify_bank_name,
    monnify_account_name: monnifyFields.monnify_account_name,
    monnify_account_reference: monnifyFields.monnify_account_reference,
    payment_deadline_at: expiryAt,
  };

  await Promise.all([
    broadcastToChannel(`session:${session_id}`, 'SHIFT_ENDED', broadcastPayload),
    broadcastToChannel(`doctor:${session.doctor_id}`, 'SHIFT_ENDED', broadcastPayload),
  ]);

  return new Response(JSON.stringify({
    success: true,
    session: updated,
    total_naira: totalNaira,
    platform_naira: platformNaira,
    doctor_naira: doctorNaira,
    account_number: monnifyFields.monnify_account_number,
    bank_name: monnifyFields.monnify_bank_name,
    account_name: monnifyFields.monnify_account_name,
    payment_deadline_at: expiryAt,
    payment: paymentIntent ? {
      id: paymentIntent.id,
