  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) return new Response(JSON.stringify({ error: 'No auth' }), { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

  const supabaseAdmin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  const supabaseUser = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_ANON_KEY')!, { global: { headers: { Authorization: authHeader } } });

  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

  // Accept optional doctor_id override (for inline fallback calls from end-shift using service role)
  let body: { doctor_id?: string } = {};
  try { body = await req.json(); } catch { /* no body is fine */ }
  const doctorId = body.doctor_id ?? user.id;

  // Check if already provisioned
  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code, reserved_account_number, reserved_account_bank, reserved_account_reference, reserved_account_name, account_name, bank_name, bank_code, account_number')
    .eq('id', doctorId)
    .single();

  if (!doctorProfile) return new Response(JSON.stringify({ error: 'Doctor profile not found' }), { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });

  // Already provisioned — return stored details
  if (doctorProfile.reserved_account_number) {
    console.log('[provision-reserved-account] Already provisioned for doctor:', doctorId);
    return new Response(JSON.stringify({
      success: true,
      already_existed: true,
      account_number: doctorProfile.reserved_account_number,
      bank_name: doctorProfile.reserved_account_bank,
      account_reference: doctorProfile.reserved_account_reference,
      account_name: doctorProfile.reserved_account_name,
    }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  }

  // Need to provision — get Monnify credentials
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');
  if (!apiKey || !secretKey || !contractCode) {
    return new Response(JSON.stringify({ error: 'Monnify credentials not configured' }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';

  // Get Monnify token
  const credentials = btoa(`${apiKey}:${secretKey}`);
  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: { Authorization: `Basic ${credentials}`, 'Content-Type': 'application/json' },
  });
  const authData = await authRes.json();
  if (!authRes.ok || !authData.requestSuccessful) {
    return new Response(JSON.stringify({ error: `Monnify auth failed: ${authData.responseMessage ?? 'unknown'}` }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  }
  const accessToken = authData.responseBody?.accessToken;

  // Fetch doctor's name from profiles
  const { data: profile } = await supabaseAdmin.from('profiles').select('first_name, last_name').eq('id', doctorId).single();
  const doctorName = profile ? `${profile.first_name ?? ''} ${profile.last_name ?? ''}`.trim() : (doctorProfile.account_name ?? 'Doctor');

  // Deterministic account reference scoped to doctor
  const accountReference = `FLD-${doctorId.replace(/-/g, '').slice(0, 20)}`;
  console.log('[provision-reserved-account] accountReference:', accountReference);

  // Build POST body
  const postBody: Record<string, unknown> = {
    accountReference,
    accountName: `FlashLocum / ${doctorName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: `doctor-${doctorId.slice(0, 8)}@flashlocum.com`,
    customerName: doctorName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (doctorProfile.subaccount_code) {
    postBody.incomeSplitConfig = [{
      subAccountCode: doctorProfile.subaccount_code,
      feePercentage: 0,
      splitPercentage: 85,
      feeBearer: false,
    }];
  }

  // Try GET first (idempotency)
  let accountNumber = '';
  let bankName = '';
  let accountName = '';
  let finalReference = accountReference;

  const getRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts/${accountReference}`, {
    headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
  });
  const getData = await getRes.json();
  console.log('[provision-reserved-account] GET status:', getRes.status, JSON.stringify(getData));

  if ((getRes.ok || getData.requestSuccessful) && getData.responseBody) {
    const rb = getData.responseBody;
    const acct = rb.accounts?.[0];
    accountNumber = acct?.accountNumber ?? rb.accountNumber ?? '';
    bankName = acct?.bankName ?? rb.bankName ?? '';
    accountName = rb.accountName ?? '';
    finalReference = rb.accountReference ?? accountReference;
    console.log('[provision-reserved-account] Found existing via GET');
  } else {
    // POST to create
    const postRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(postBody),
    });
    const postData = await postRes.json();
    console.log('[provision-reserved-account] POST status:', postRes.status, JSON.stringify(postData));

    if (!postRes.ok || !postData.requestSuccessful) {
      return new Response(JSON.stringify({ error: `Monnify error (HTTP ${postRes.status}): ${postData.responseMessage ?? JSON.stringify(postData)}` }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    const rb = postData.responseBody;
    const acct = rb.accounts?.[0];
    accountNumber = acct?.accountNumber ?? rb.accountNumber ?? '';
    bankName = acct?.bankName ?? rb.bankName ?? '';
    accountName = rb.accountName ?? '';
    finalReference = rb.accountReference ?? accountReference;
  }

  // Store in doctor_profiles
  await supabaseAdmin.from('doctor_profiles').update({
    reserved_account_number: accountNumber,
    reserved_account_bank: bankName,
    reserved_account_reference: finalReference,
    reserved_account_name: accountName,
    reserved_account_provisioned_at: new Date().toISOString(),
  }).eq('id', doctorId);

  console.log('[provision-reserved-account] Stored for doctor:', doctorId, accountNumber, bankName);

  return new Response(JSON.stringify({
    success: true,
    already_existed: false,
    account_number: accountNumber,
    bank_name: bankName,
    account_reference: finalReference,
    account_name: accountName,
  }), { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
});
