## 3. `monnify-webhook` (version 4)

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

async function broadcastToChannel(supabaseUrl: string, serviceRoleKey: string, channel: string, event: string, payload: object): Promise<void> {
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`[monnify-webhook] Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[monnify-webhook] Broadcast OK to ${channel} event=${event}`);
  }
}

async function computeSha512(message: string, secret: string): Promise<string> {
  const encoder = new TextEncoder();
  // Monnify uses SHA512(secretKey + "|" + transactionReference) as a plain hash, not HMAC
  // But the spec says to use HMAC-SHA512 with the secret key
  // We support both: first try HMAC-SHA512 (as per task spec), fallback handled by caller
  const keyData = encoder.encode(secret);
  const msgData = encoder.encode(message);
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-512' },
    false,
    ['sign']
  );
  const signature = await crypto.subtle.sign('HMAC', cryptoKey, msgData);
  return Array.from(new Uint8Array(signature))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

async function computePlainSha512(data: string): Promise<string> {
  const encoder = new TextEncoder();
  const hashBuffer = await crypto.subtle.digest('SHA-512', encoder.encode(data));
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const monnifySecretKey = Deno.env.get('MONNIFY_SECRET_KEY') ?? '';

  // Read raw body for signature verification
  const rawBody = await req.text();

  // Verify Monnify signature
  // Monnify sends SHA512(secretKey + "|" + transactionReference) in monnify-signature header
  const monnifySignature = req.headers.get('monnify-signature') ?? '';

  if (monnifySecretKey && monnifySignature) {
    let event: { eventType?: string; eventData?: Record<string, unknown> };
    try {
      event = JSON.parse(rawBody);
    } catch {
      return new Response(JSON.stringify({ error: 'Invalid JSON' }), { status: 400, headers: { 'Content-Type': 'application/json' } });
    }

    const transactionReference = (event.eventData as Record<string, unknown>)?.transactionReference as string ?? '';
    // Monnify signature: SHA512(secretKey + "|" + transactionReference)
    const plainHash = await computePlainSha512(`${monnifySecretKey}|${transactionReference}`);

    if (plainHash.toLowerCase() !== monnifySignature.toLowerCase()) {
      // Also try HMAC-SHA512 as fallback
      const hmacHash = await computeSha512(rawBody, monnifySecretKey);
      if (hmacHash.toLowerCase() !== monnifySignature.toLowerCase()) {
        console.error('[monnify-webhook] Signature mismatch. plainHash:', plainHash, 'hmacHash:', hmacHash, 'Got:', monnifySignature);
        return new Response(JSON.stringify({ error: 'Invalid signature' }), {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        });
      }
    }
  }

  let event: { eventType?: string; eventData?: Record<string, unknown> };
  try {
    event = JSON.parse(rawBody);
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON' }), { status: 400, headers: { 'Content-Type': 'application/json' } });
  }

  const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey);
  const eventType = event.eventType;
  const eventData = event.eventData ?? {};

  console.log(`[monnify-webhook] Received event: ${eventType}`);

  if (eventType === 'SUCCESSFUL_TRANSACTION') {
    const reference = (eventData.product as Record<string, unknown>)?.reference as string;
    const paymentStatus = eventData.paymentStatus as string;
    const amountPaid = Number(eventData.amountPaid ?? 0);
    const transactionReference = eventData.transactionReference as string;

    console.log(`[monnify-webhook] SUCCESSFUL_TRANSACTION: reference=${reference} paymentStatus=${paymentStatus} amountPaid=${amountPaid}`);

    // Only treat PAID as success
    if (paymentStatus !== 'PAID') {
      console.log(`[monnify-webhook] Ignoring non-PAID status: ${paymentStatus}`);
      return new Response('ok', { status: 200 });
    }

    if (!reference) {
      console.error('[monnify-webhook] No reference in SUCCESSFUL_TRANSACTION event');
      return new Response('ok', { status: 200 });
    }

    // Find matching payment_intent by monnify_account_reference
    const { data: paymentIntent, error: piFetchError } = await supabaseAdmin
      .from('payment_intents')
      .select('id, session_id, status, amount_naira')
      .eq('monnify_account_reference', reference)
      .maybeSingle();

    if (piFetchError || !paymentIntent) {
      console.log('[monnify-webhook] No payment_intent found for reference:', reference, '— falling back to coverage_sessions lookup');

      // Fallback: look up session directly (for backwards compat with old flow)
      const { data: session, error: sessionFetchError } = await supabaseAdmin
        .from('coverage_sessions')
        .select('id, requester_id, doctor_id, status')
        .or(`monnify_account_reference.eq.${reference},monnify_reference.eq.${reference}`)
        .maybeSingle();

      if (sessionFetchError || !session) {
        console.error('[monnify-webhook] Session not found for reference:', reference);
        return new Response('ok', { status: 200 });
      }

      const nowIso = new Date().toISOString();
      await supabaseAdmin
        .from('coverage_sessions')
        .update({ status: 'requester_paid', updated_at: nowIso })
        .eq('id', session.id);

      const broadcastPayload = { session_id: session.id, amount_paid_naira: amountPaid, paid_at: nowIso };
      await Promise.all([
        broadcastToChannel(supabaseUrl, serviceRoleKey, `session:${session.id}`, 'payment_confirmed', broadcastPayload),
        broadcastToChannel(supabaseUrl, serviceRoleKey, `user:${session.requester_id}`, 'payment_confirmed', broadcastPayload),
        broadcastToChannel(supabaseUrl, serviceRoleKey, `user:${session.doctor_id}`, 'payment_confirmed', broadcastPayload),
      ]);

      return new Response(JSON.stringify({ success: true }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }

    // Idempotency: if already paid, do nothing
    if (paymentIntent.status === 'paid') {
      console.log('[monnify-webhook] payment_intent already paid, skipping:', paymentIntent.id);
      return new Response(JSON.stringify({ success: true }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }

    const nowIso = new Date().toISOString();
    const sessionId = paymentIntent.session_id;

    // Update payment_intent to paid
    const { error: piUpdateError } = await supabaseAdmin
      .from('payment_intents')
      .update({
        status: 'paid',
        monnify_transaction_reference: transactionReference,
        updated_at: nowIso,
      })
      .eq('id', paymentIntent.id);

    if (piUpdateError) {
      console.error('[monnify-webhook] Failed to update payment_intent:', piUpdateError);
    }

    // Update coverage_session to requester_paid
    const { error: sessionUpdateError } = await supabaseAdmin
      .from('coverage_sessions')
      .update({ status: 'requester_paid', updated_at: nowIso })
      .eq('id', sessionId);

    if (sessionUpdateError) {
      console.error('[monnify-webhook] Failed to update coverage_session:', sessionUpdateError);
    }

    // Fetch session for requester_id and doctor_id
    const { data: session } = await supabaseAdmin
      .from('coverage_sessions')
      .select('id, requester_id, doctor_id')
      .eq('id', sessionId)
      .single();

    if (session) {
      const broadcastPayload = {
        session_id: sessionId,
        amount_paid_naira: amountPaid,
        paid_at: nowIso,
      };

      await Promise.all([
        broadcastToChannel(supabaseUrl, serviceRoleKey, `session:${sessionId}`, 'payment_confirmed', broadcastPayload),
        broadcastToChannel(supabaseUrl, serviceRoleKey, `user:${session.requester_id}`, 'payment_confirmed', broadcastPayload),
        broadcastToChannel(supabaseUrl, serviceRoleKey, `user:${session.doctor_id}`, 'payment_confirmed', broadcastPayload),
      ]);
    }

    console.log(`[monnify-webhook] SUCCESSFUL_TRANSACTION processed for session ${sessionId}`);
    return new Response(JSON.stringify({ success: true }), { status: 200, headers: { 'Content-Type': 'application/json' } });
  }

  if (eventType === 'SETTLEMENT_COMPLETED') {
    const destinationAccountNumber = eventData.destinationAccountNumber as string;
    const settlementReference = eventData.reference as string;

    let session: { id: string; requester_id: string; doctor_id: string } | null = null;

    if (settlementReference) {
      const { data } = await supabaseAdmin
        .from('coverage_sessions')
        .select('id, requester_id, doctor_id')
        .or(`monnify_account_reference.eq.${settlementReference},monnify_reference.eq.${settlementReference}`)
        .maybeSingle();
      session = data;
    }

    if (!session && destinationAccountNumber) {
      const { data } = await supabaseAdmin
        .from('coverage_sessions')
        .select('id, requester_id, doctor_id')
        .eq('monnify_account_number', destinationAccountNumber)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      session = data;
    }

    if (!session) {
      console.error('[monnify-webhook] Session not found for SETTLEMENT_COMPLETED event');
      return new Response('ok', { status: 200 });
    }

    const nowIso = new Date().toISOString();
    await supabaseAdmin
      .from('coverage_sessions')
      .update({ status: 'payment_complete', payment_complete_at: nowIso, updated_at: nowIso })
      .eq('id', session.id);

    const broadcastPayload = { session_id: session.id, status: 'payment_complete' };
    await Promise.all([
      broadcastToChannel(supabaseUrl, serviceRoleKey, `session:${session.id}`, 'PAYMENT_COMPLETE', broadcastPayload),
      broadcastToChannel(supabaseUrl, serviceRoleKey, `requester:${session.requester_id}`, 'PAYMENT_COMPLETE', broadcastPayload),
      broadcastToChannel(supabaseUrl, serviceRoleKey, `doctor:${session.doctor_id}`, 'PAYMENT_COMPLETE', broadcastPayload),
    ]);

    console.log(`[monnify-webhook] SETTLEMENT_COMPLETED processed for session ${session.id}`);
    return new Response('ok', { status: 200 });
  }

  console.log(`[monnify-webhook] Ignoring unknown event type: ${eventType}`);
  return new Response('ok', { status: 200 });
});
