## 4. `monnify-disbursement-webhook` (version 1)

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

async function broadcastToChannel(
  supabaseUrl: string,
  serviceRoleKey: string,
  channel: string,
  event: string,
  payload: object
): Promise<void> {
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(
      `[monnify-disbursement-webhook] Broadcast error [${channel}]: ${response.status} ${await response.text()}`
    );
  } else {
    console.log(`[monnify-disbursement-webhook] Broadcast OK to ${channel} event=${event}`);
  }
}

async function computePlainSha512(data: string): Promise<string> {
  const encoder = new TextEncoder();
  const hashBuffer = await crypto.subtle.digest('SHA-512', encoder.encode(data));
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

async function computeHmacSha512(message: string, secret: string): Promise<string> {
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const msgData = encoder.encode(message);
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-512' },
    false,
    ['sign']
  );
  const signature = await crypto.subtle.sign('HMAC', cryptoKey, msgData);
  return Array.from(new Uint8Array(signature))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const monnifySecretKey = Deno.env.get('MONNIFY_SECRET_KEY') ?? '';

  const rawBody = await req.text();

  let event: { eventType?: string; eventData?: Record<string, unknown> };
  try {
    event = JSON.parse(rawBody);
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  // Verify Monnify signature: SHA512(secretKey + "|" + transactionReference)
  const monnifySignature = req.headers.get('monnify-signature') ?? '';
  if (monnifySecretKey && monnifySignature) {
    const transactionReference =
      (event.eventData?.transactionReference as string) ?? '';

    const plainHash = await computePlainSha512(
      `${monnifySecretKey}|${transactionReference}`
    );

    if (plainHash.toLowerCase() !== monnifySignature.toLowerCase()) {
      // Fallback: try HMAC-SHA512 over raw body
      const hmacHash = await computeHmacSha512(rawBody, monnifySecretKey);
      if (hmacHash.toLowerCase() !== monnifySignature.toLowerCase()) {
        console.error(
          '[monnify-disbursement-webhook] Signature mismatch. plainHash:',
          plainHash,
          'hmacHash:',
          hmacHash,
          'Got:',
          monnifySignature
        );
        return new Response(JSON.stringify({ error: 'Invalid signature' }), {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        });
      }
    }
  }

  const eventType = event.eventType;
  const eventData = event.eventData ?? {};

  console.log(`[monnify-disbursement-webhook] Received event: ${eventType}`);

  // Only handle SUCCESSFUL_DISBURSEMENT
  if (eventType !== 'SUCCESSFUL_DISBURSEMENT') {
    console.log(
      `[monnify-disbursement-webhook] Ignoring event type: ${eventType}`
    );
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const disbursementStatus = eventData.status as string;
  if (disbursementStatus !== 'SUCCESS') {
    console.log(
      `[monnify-disbursement-webhook] Disbursement status is not SUCCESS: ${disbursementStatus}`
    );
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const transferCode = eventData.transferCode as string | undefined;
  const transactionReference = eventData.transactionReference as string | undefined;
  const destinationAccountNumber = eventData.destinationAccountNumber as string | undefined;
  const disbursedAmount = Number(eventData.amount ?? 0);

  const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey);

  // Find matching payment_intent
  // Strategy 1: match by monnify_transaction_reference
  let paymentIntent: {
    id: string;
    session_id: string;
    disbursed_at: string | null;
    amount_naira: number;
  } | null = null;

  if (transactionReference) {
    const { data } = await supabaseAdmin
      .from('payment_intents')
      .select('id, session_id, disbursed_at, amount_naira')
      .eq('monnify_transaction_reference', transactionReference)
      .maybeSingle();
    paymentIntent = data;
  }

  // Strategy 2: match by destination account number + status = 'paid'
  if (!paymentIntent && destinationAccountNumber) {
    const { data } = await supabaseAdmin
      .from('payment_intents')
      .select('id, session_id, disbursed_at, amount_naira')
      .eq('monnify_account_number', destinationAccountNumber)
      .eq('status', 'paid')
      .order('created_at', { ascending: false })
      .limit(1)
      .maybeSingle();
    paymentIntent = data;
  }

  if (!paymentIntent) {
    console.log(
      '[monnify-disbursement-webhook] No matching payment_intent found. Logging payload:',
      JSON.stringify(eventData)
    );
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  // Idempotency: already processed
  if (paymentIntent.disbursed_at) {
    console.log(
      '[monnify-disbursement-webhook] Already disbursed, skipping:',
      paymentIntent.id
    );
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  const nowIso = new Date().toISOString();
  const disbursementRef = transferCode ?? transactionReference ?? '';

  // Update payment_intent with disbursement info
  const { error: piUpdateError } = await supabaseAdmin
    .from('payment_intents')
    .update({
      disbursement_reference: disbursementRef,
      disbursed_at: nowIso,
      updated_at: nowIso,
    })
    .eq('id', paymentIntent.id);

  if (piUpdateError) {
    console.error(
      '[monnify-disbursement-webhook] Failed to update payment_intent:',
      piUpdateError
    );
  }

  // Update coverage_session to 'disbursed'
  const { error: sessionUpdateError } = await supabaseAdmin
    .from('coverage_sessions')
    .update({ status: 'disbursed', updated_at: nowIso })
    .eq('id', paymentIntent.session_id);

  if (sessionUpdateError) {
    console.error(
      '[monnify-disbursement-webhook] Failed to update coverage_session:',
      sessionUpdateError
    );
  }

  // Fetch session for doctor_id and requester_id
  const { data: session } = await supabaseAdmin
    .from('coverage_sessions')
    .select('id, doctor_id, requester_id, total_cost')
    .eq('id', paymentIntent.session_id)
    .single();

  if (!session) {
    console.error(
      '[monnify-disbursement-webhook] Could not fetch session for broadcast:',
      paymentIntent.session_id
    );
    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  }

  // Calculate net payout (85% of total, rounded to nearest 10)
  const totalCost = Number(session.total_cost ?? 0);
  const platformFee = Math.round((totalCost * 0.15) / 10) * 10;
  const netPayout = totalCost - platformFee;

  const broadcastPayload = {
    session_id: paymentIntent.session_id,
    disbursed_at: nowIso,
    net_payout_naira: netPayout,
  };

  // Broadcast to session channel and doctor's user channel
  await Promise.all([
    broadcastToChannel(
      supabaseUrl,
      serviceRoleKey,
      `session:${paymentIntent.session_id}`,
      'disbursement_confirmed',
      broadcastPayload
    ),
    broadcastToChannel(
      supabaseUrl,
      serviceRoleKey,
      `user:${session.doctor_id}`,
      'disbursement_confirmed',
      broadcastPayload
    ),
  ]);

  console.log(
    `[monnify-disbursement-webhook] Disbursement processed for session ${paymentIntent.session_id}, doctor ${session.doctor_id}, net_payout=${netPayout}`
  );

  return new Response(JSON.stringify({ success: true }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
});
