## 5. `create-subaccount` (version 8)

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

/**
 * Authenticate with Monnify and return a bearer access token.
 */
async function getMonnifyToken(baseUrl: string, apiKey: string, secretKey: string): Promise<string> {
  const credentials = btoa(`${apiKey}:${secretKey}`);
  console.log('[create-subaccount] Requesting Monnify token from:', `${baseUrl}/api/v1/auth/login`);

  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
  });

  const authData = await authRes.json();
  console.log('[create-subaccount] Monnify auth HTTP status:', authRes.status);

  if (!authRes.ok || !authData.requestSuccessful) {
    const errMsg = authData.responseMessage ?? `Monnify auth error: HTTP ${authRes.status}`;
    throw new Error(`Monnify authentication failed: ${errMsg}`);
  }

  const token = authData.responseBody?.accessToken;
  if (!token) {
    throw new Error('Monnify auth succeeded but no accessToken in response: ' + JSON.stringify(authData));
  }
  return token;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405, headers: corsHeaders });
  }

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) {
    return new Response(JSON.stringify({ error: 'Missing authorization header' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  let body: { doctor_id?: string; bank_code?: string; account_number?: string; account_name?: string; bank_name?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const { doctor_id, bank_code, account_number, account_name, bank_name } = body;
  if (!doctor_id || !bank_code || !account_number || !account_name || !bank_name) {
    return new Response(JSON.stringify({ error: 'Missing required fields: doctor_id, bank_code, account_number, account_name, bank_name' }), {
      status: 400,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Ownership: the caller must be the doctor themselves
  if (user.id !== doctor_id) {
    return new Response(JSON.stringify({ error: 'Forbidden: you can only create a subaccount for yourself' }), {
      status: 403,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Get doctor email from auth
  const { data: { user: doctorUser } } = await supabaseAdmin.auth.admin.getUserById(doctor_id);
  const doctorEmail = doctorUser?.email ?? 'noreply@flashlocum.com';

  // Determine Monnify base URL
  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';
  console.log(`[create-subaccount] Monnify env=${monnifyEnv ?? 'live'} baseUrl=${baseUrl}`);

  const apiKey = Deno.env.get('MONNIFY_API_KEY')!;
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY')!;
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey) {
    console.error('[create-subaccount] Missing Monnify credentials');
    return new Response(JSON.stringify({ error: 'Monnify credentials not configured on server' }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (!contractCode) {
    console.error('[create-subaccount] MONNIFY_CONTRACT_CODE is not set');
    return new Response(JSON.stringify({ error: 'MONNIFY_CONTRACT_CODE not configured on server' }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  let subAccountCode: string;
  try {
    // Step 1: Authenticate with Monnify to get bearer token
    const accessToken = await getMonnifyToken(baseUrl, apiKey, secretKey);
    console.log('[create-subaccount] Monnify token obtained successfully');

    // Step 2: Create sub-account
    // IMPORTANT: Monnify's POST /api/v1/sub-accounts requires an ARRAY body,
    // not a plain object. Sending a plain object returns 400 "malformed syntax".
    const monnifyPayload = [{
      contractCode,
      currencyCode: 'NGN',
      bankCode: bank_code,
      accountNumber: account_number,
      email: doctorEmail,
      subAccountName: account_name,
      defaultSplitPercentage: 85,
    }];

    console.log('[create-subaccount] Calling Monnify sub-accounts API with array body:', JSON.stringify(monnifyPayload));

    const response = await fetch(`${baseUrl}/api/v1/sub-accounts`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(monnifyPayload),
    });

    const data = await response.json();
    console.log('[create-subaccount] Monnify sub-accounts HTTP status:', response.status);
    console.log('[create-subaccount] Monnify sub-accounts response:', JSON.stringify(data));

    if (!response.ok || !data.requestSuccessful) {
      const errMsg = data.responseMessage ?? `Monnify error: HTTP ${response.status}`;
      console.error('[create-subaccount] Monnify sub-accounts failed:', errMsg);
      return new Response(JSON.stringify({ error: errMsg, monnify_response: data }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // responseBody is an array; grab the first element's subAccountCode
    const createdAccount = Array.isArray(data.responseBody)
      ? data.responseBody[0]
      : data.responseBody;

    subAccountCode = createdAccount?.subAccountCode;
    if (!subAccountCode) {
      console.error('[create-subaccount] No subAccountCode in response:', JSON.stringify(data));
      return new Response(JSON.stringify({ error: 'No subAccountCode returned from Monnify', monnify_response: data }), {
        status: 400,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'Unknown error calling Monnify';
    console.error('[create-subaccount] Exception:', msg);
    return new Response(JSON.stringify({ error: msg }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Store subaccount_code in doctor_profiles
  const { data: updatedRows, error: upsertError } = await supabaseAdmin
    .from('doctor_profiles')
    .update({ subaccount_code: subAccountCode, updated_at: new Date().toISOString() })
    .eq('id', doctor_id)
    .select('id');

  if (upsertError) {
    console.error('[create-subaccount] DB update error:', upsertError.message);
    return new Response(JSON.stringify({ error: upsertError.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (!updatedRows || updatedRows.length === 0) {
    console.error('[create-subaccount] No doctor_profiles row found for doctor_id:', doctor_id);
    return new Response(JSON.stringify({ error: 'Doctor profile not found — cannot store subaccount code' }), {
      status: 404,
