Here is the **complete, verbatim source** of the `get-active-session` edge function (`index.ts`):

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET, OPTIONS',
};

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: req.headers.get('Authorization')! } } }
  );

  const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const url = new URL(req.url);
  const role = url.searchParams.get('role') ?? 'requester';

  const column = role === 'doctor' ? 'doctor_id' : 'requester_id';
  const activeStatuses = ['upcoming', 'active', 'paused', 'payment_pending'];

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );

  const { data, error } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq(column, user.id)
    .in('status', activeStatuses)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (!data) {
    return new Response(JSON.stringify({ session: null }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Enrich session with phone numbers from profiles
  const [{ data: doctorProfile }, { data: requesterProfile }] = await Promise.all([
    supabaseAdmin.from('profiles').select('phone').eq('id', data.doctor_id).single(),
    supabaseAdmin.from('profiles').select('phone').eq('id', data.requester_id).single(),
  ]);

  const sessionWithPhones = {
    ...data,
    doctor_phone: doctorProfile?.phone ?? null,
    requester_phone: requesterProfile?.phone ?? null,
  };

  return new Response(JSON.stringify({ session: sessionWithPhones }), {
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
```

That is every line of the function — nothing omitted or truncated.

