## `calculate-price` — `index.ts`

```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { calculateBill, resolveHourlyRateKobo, buildCoverageLabel, resolveEffectiveCoverageType } from './_shared/billing.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

/**
 * Returns true if the total hours exactly matches a straight coverage tier.
 * e.g. duration_hours=24 with coverage_length=1 → 24h straight
 */
function isExactStraightDuration(totalHours: number): boolean {
  return totalHours === 24 || totalHours === 48 || totalHours === 72;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: corsHeaders });

  try {
    const body = await req.json();
    const {
      coverage_type,
      shift_type,
      environment,
      duration_hours,
      coverage_length = 1,
      start_hour,
      start_time,
      end_time,
    } = body;

    if (!coverage_type || !shift_type || !environment || duration_hours == null) {
      return new Response(JSON.stringify({ error: 'Missing required fields' }), {
        status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
    );

    const { data: config, error: configError } = await supabase
      .from('pricing_config')
      .select('day_rate_short, day_rate_medium, day_rate_long, night_rate, home_care_rate, busy_multiplier, straight_24h_flat_kobo, straight_48h_flat_kobo, straight_72h_flat_kobo, straight_overage_rate_kobo')
      .single();

    if (configError || !config) {
      return new Response(JSON.stringify({ error: 'Pricing config not found' }), {
        status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      });
    }

    // Step 1: auto-detect straight coverage from start_time === end_time
    let effectiveCoverageType = resolveEffectiveCoverageType(
      coverage_type,
      coverage_length,
      start_time,
      end_time
    );

    // Step 2: also detect by exact total duration (24/48/72h) if not already straight
    const totalDurationHours = duration_hours * coverage_length;
    if (!effectiveCoverageType.toLowerCase().includes('straight') && isExactStraightDuration(totalDurationHours)) {
      effectiveCoverageType = resolveEffectiveCoverageType(coverage_type, coverage_length);
    }

    console.log(`[calculate-price] coverage_type=${coverage_type} effectiveCoverageType=${effectiveCoverageType} duration_hours=${duration_hours} coverage_length=${coverage_length}`);

    const isStraight = effectiveCoverageType.toLowerCase().includes('straight');

    // For straight coverage: pass total hours as one block, coverage_length=1
    // For segmented: pass per-day hours, multiply by days
    let billingDurationHours: number;
    let billingCoverageLength: number;

    if (isStraight) {
      billingDurationHours = 24 * coverage_length; // total straight hours
      billingCoverageLength = 1;
    } else {
      billingDurationHours = duration_hours;
      billingCoverageLength = coverage_length;
    }

    const hourlyRateKobo = resolveHourlyRateKobo(shift_type, effectiveCoverageType, billingDurationHours, config);
    const bookedSeconds = billingDurationHours * 3600;

    const singleDayResult = calculateBill({
      coverageType: effectiveCoverageType,
      shiftType: shift_type,
      environment,
      bookedDurationSeconds: bookedSeconds,
      actualDurationSeconds: bookedSeconds,
      hourlyRateKobo,
      nightRateKobo: Math.round(config.night_rate * 100),
      busyMultiplier: config.busy_multiplier ?? 1.3,
      startHour: start_hour,
      straight24hFlatKobo: config.straight_24h_flat_kobo,
      straight48hFlatKobo: config.straight_48h_flat_kobo,
      straight72hFlatKobo: config.straight_72h_flat_kobo,
      straightOverageRateKobo: config.straight_overage_rate_kobo,
    });

    // For segmented (non-straight) bookings, multiply by number of days
    const days = singleDayResult.mode === 'segmented' ? Math.max(1, billingCoverageLength) : 1;
    const totalAmountKobo = singleDayResult.amountKobo * days;
    const totalAmountNaira = totalAmountKobo / 100;
    const totalHours = singleDayResult.billableHours * days;

    // Build the descriptive label
    const label = buildCoverageLabel(effectiveCoverageType, totalHours, days);

    return new Response(JSON.stringify({
      duration_hours: totalHours,
      price: totalAmountNaira,
      price_kobo: totalAmountKobo,
      label,
      mode: singleDayResult.mode,
      coverage_type: effectiveCoverageType,
    }), {
      status: 200,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  } catch (err) {
    console.error('[calculate-price]', err);
    return new Response(JSON.stringify({ error: 'Internal server error' }), {
      status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }
});
