```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(supabaseUrl: string, serviceRoleKey: string, channel: string, event: string, payload: object): Promise<void> {
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`[extend-payment] Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  }
}

async function createMonnifyReservedAccount(
  accountReference: string,
  hospitalName: string,
  requesterName: string,
  requesterEmail: string,
  subaccountCode: string | null
): Promise<{ accountNumber: string; bankName: string; accountName: string; reference: string }> {
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    throw new Error('Monnify credentials not configured: missing MONNIFY_API_KEY, MONNIFY_SECRET_KEY, or MONNIFY_CONTRACT_CODE');
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';
  console.log(`[extend-payment] Monnify env=${monnifyEnv ?? 'live'} baseUrl=${baseUrl}`);

  const credentials = btoa(`${apiKey}:${secretKey}`);

  const body: Record<string, unknown> = {
    accountReference,
    accountName: `FlashLocum / ${hospitalName}`,
    currencyCode: 'NGN',
    contractCode,
    customerEmail: requesterEmail,
    customerName: requesterName,
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode && subaccountCode.trim()) {
    body.incomeSplitConfig = [
      {
        subAccountCode: subaccountCode,
        feePercentage: 0,
        splitPercentage: 85,
        feeBearer: false,
      },
    ];
  }

  const response = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${credentials}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  const data = await response.json();
  console.log('[extend-payment] Monnify HTTP status:', response.status);
  console.log('[extend-payment] Monnify response:', JSON.stringify(data));

  if (!response.ok || !data.requestSuccessful) {
    throw new Error(`Monnify error (HTTP ${response.status}): ${data.responseMessage ?? JSON.stringify(data)}`);
  }

  const rb = data.responseBody;
  const account = rb.accounts?.[0];

  return {
    accountNumber: account?.accountNumber ?? rb.accountNumber ?? '',
    bankName: account?.bankName ?? rb.bankName ?? '',
    accountName: rb.accountName ?? '',
    reference: rb.accountReference ?? accountReference,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey);

  // Find all expired payment_pending sessions that haven't had a late fee applied recently
  // NOTE: uses coverage_length (integer hours) — there is no duration_hours column
  const { data: expiredSessions, error: fetchError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('id, requester_id, doctor_id, price, coverage_length, payment_deadline_at, late_fee_applied_at, hospital_name, requester_name, monnify_account_reference, monnify_reference')
    .eq('status', 'payment_pending')
    .lt('payment_deadline_at', new Date().toISOString())
    .or('late_fee_applied_at.is.null,late_fee_applied_at.lt.' + new Date(Date.now() - 14 * 60 * 1000).toISOString());

  if (fetchError) {
    console.error('[extend-payment] Error fetching expired sessions:', fetchError.message);
    return new Response(JSON.stringify({ error: fetchError.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (!expiredSessions || expiredSessions.length === 0) {
    console.log('[extend-payment] No expired sessions to process');
    return new Response(JSON.stringify({ processed: 0 }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  console.log(`[extend-payment] Processing ${expiredSessions.length} expired session(s)`);

  const results: { session_id: string; success: boolean; error?: string }[] = [];

  for (const session of expiredSessions) {
    try {
      // Calculate late fee: hourly rate / 4 (15 minutes of work)
      // coverage_length is in hours; use it as the duration denominator
      const durationHours = Number(session.coverage_length) || 1;
      const currentPrice = Number(session.price) || 0;
      const lateFee = Math.round(currentPrice / durationHours / 4);
      const newPrice = currentPrice + lateFee;

      // Get doctor's subaccount_code — doctor_profiles.id = user UUID (FK to profiles.id)
      const { data: doctorProfile } = await supabaseAdmin
        .from('doctor_profiles')
        .select('subaccount_code')
        .eq('id', session.doctor_id)
        .maybeSingle();

      const subaccountCode = doctorProfile?.subaccount_code ?? null;

      // Get requester email
      const { data: { user: requesterUser } } = await supabaseAdmin.auth.admin.getUserById(session.requester_id);
      const requesterEmail = requesterUser?.email ?? 'noreply@flashlocum.com';

      // Create a new unique account reference for this extension
      const newReference = `${session.id}-ext-${Date.now()}`;

      // Reserve a new Monnify virtual account
      const monnifyData = await createMonnifyReservedAccount(
        newReference,
        session.hospital_name ?? 'FlashLocum',
        session.requester_name ?? 'Requester',
        requesterEmail,
        subaccountCode
      );

      const now = new Date();
      const newDeadline = new Date(now.getTime() + 15 * 60 * 1000).toISOString();
      const nowIso = now.toISOString();

      // Update session
      const { error: updateError } = await supabaseAdmin
        .from('coverage_sessions')
        .update({
          price: newPrice,
          monnify_account_number: monnifyData.accountNumber,
          monnify_bank_name: monnifyData.bankName,
          monnify_account_name: monnifyData.accountName,
          monnify_account_reference: monnifyData.reference,
          monnify_reference: monnifyData.reference,
          payment_deadline_at: newDeadline,
          late_fee_applied_at: nowIso,
          updated_at: nowIso,
        })
        .eq('id', session.id);

      if (updateError) {
        throw new Error(updateError.message);
      }

      const broadcastPayload = {
        session_id: session.id,
        late_fee: lateFee,
        new_total: newPrice,
        new_deadline: newDeadline,
        account_number: monnifyData.accountNumber,
        bank_name: monnifyData.bankName,
        account_name: monnifyData.accountName,
      };

      await Promise.all([
        broadcastToChannel(supabaseUrl, serviceRoleKey, `session:${session.id}`, 'PAYMENT_DEADLINE_EXTENDED', broadcastPayload),
        broadcastToChannel(supabaseUrl, serviceRoleKey, `requester:${session.requester_id}`, 'PAYMENT_DEADLINE_EXTENDED', broadcastPayload),
      ]);

      console.log(`[extend-payment] Processed session ${session.id}: lateFee=${lateFee} newPrice=${newPrice}`);
      results.push({ session_id: session.id, success: true });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Unknown error';
      console.error(`[extend-payment] Error processing session ${session.id}:`, msg);
      results.push({ session_id: session.id, success: false, error: msg });
    }
  }

  const allFailed = results.every(r => !r.success);
  return new Response(JSON.stringify({ processed: results.length, results }), {
    status: allFailed && results.length > 0 ? 500 : 200,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
