import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { splitNaira, fetchPricingRules } from './_shared/billing.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

async function broadcastToChannel(channel: string, event: string, payload: object): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [{ topic: `realtime:${channel}`, event: 'broadcast', payload: { event, payload } }],
    }),
  });
  if (!response.ok) {
    console.error(`[refresh-payment] Broadcast error [${channel}]: ${response.status} ${await response.text()}`);
  } else {
    console.log(`[refresh-payment] Broadcast OK to ${channel} event=${event}`);
  }
}

// Module-level Monnify token cache
let cachedToken: string | null = null;
let tokenExpiresAt: number = 0;

async function getMonnifyToken(baseUrl: string, apiKey: string, secretKey: string): Promise<string> {
  const now = Date.now();
  if (cachedToken && tokenExpiresAt - now > 60_000) {
    return cachedToken;
  }
  const credentials = btoa(`${apiKey}:${secretKey}`);
  const authRes = await fetch(`${baseUrl}/api/v1/auth/login`, {
    method: 'POST',
    headers: { Authorization: `Basic ${credentials}`, 'Content-Type': 'application/json' },
  });
  const authData = await authRes.json();
  if (!authRes.ok || !authData.requestSuccessful) {
    throw new Error(`Monnify auth failed: ${authData.responseMessage ?? `HTTP ${authRes.status}`}`);
  }
  const token = authData.responseBody?.accessToken;
  const expiresIn = authData.responseBody?.expiresIn ?? 3600;
  if (!token) throw new Error('No accessToken in Monnify auth response');
  const jitter = 60 + Math.floor(Math.random() * 120);
  cachedToken = token;
  tokenExpiresAt = now + (expiresIn - jitter) * 1000;
  return token;
}

async function reserveNewMonnifyAccount(
  sessionId: string,
  doctorId: string,
  subaccountCode: string | null | undefined,
  supabaseAdmin: ReturnType<typeof createClient>
): Promise<{ accountNumber: string; bankName: string; accountReference: string; accountName: string }> {
  const apiKey = Deno.env.get('MONNIFY_API_KEY');
  const secretKey = Deno.env.get('MONNIFY_SECRET_KEY');
  const contractCode = Deno.env.get('MONNIFY_CONTRACT_CODE');

  if (!apiKey || !secretKey || !contractCode) {
    throw new Error('Monnify credentials not configured');
  }

  const monnifyEnv = Deno.env.get('MONNIFY_ENV');
  const baseUrl = monnifyEnv === 'sandbox' ? 'https://sandbox.monnify.com' : 'https://api.monnify.com';

  const accessToken = await getMonnifyToken(baseUrl, apiKey, secretKey);

  // Use session_id + timestamp as unique reference for this cycle
  const accountReference = `${sessionId.replace(/-/g, '').slice(0, 20)}_${Date.now()}`;
  console.log('[refresh-payment] New Monnify accountReference:', accountReference);

  const postBody: Record<string, unknown> = {
    accountReference,
    accountName: 'FlashLocum',
    currencyCode: 'NGN',
    contractCode,
    customerEmail: `session-${sessionId.slice(0, 8)}@flashlocum.com`,
    customerName: 'FlashLocum',
    getAllAvailableBanks: false,
    preferredBanks: ['035'],
  };

  if (subaccountCode) {
    postBody.incomeSplitConfig = [{
      subAccountCode: subaccountCode,
      feePercentage: 0,
      splitPercentage: 85,
      feeBearer: false,
    }];
  }

  const postRes = await fetch(`${baseUrl}/api/v2/bank-transfer/reserved-accounts`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
    body: JSON.stringify(postBody),
  });
  const postData = await postRes.json();
  console.log('[refresh-payment] Monnify reserve POST status:', postRes.status, JSON.stringify(postData));

  if (!postRes.ok || !postData.requestSuccessful) {
    throw new Error(`Monnify error (HTTP ${postRes.status}): ${postData.responseMessage ?? JSON.stringify(postData)}`);
  }

  const rb = postData.responseBody;
  const acct = rb.accounts?.[0];
  const accountNumber = acct?.accountNumber ?? rb.accountNumber ?? '';
  const bankName = acct?.bankName ?? rb.bankName ?? '';
  const accountName = rb.accountName ?? 'FlashLocum';
  const finalReference = rb.accountReference ?? accountReference;

  return { accountNumber, bankName, accountReference: finalReference, accountName };
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: corsHeaders });

  const authHeader = req.headers.get('Authorization');
  if (!authHeader) return new Response(JSON.stringify({ error: 'No auth' }), { status: 401, headers: corsHeaders });

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: authHeader } } }
  );

  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), { status: 401, headers: corsHeaders });
  }

  let body: { session_id?: string };
  try {
    body = await req.json();
  } catch {
    return new Response(JSON.stringify({ error: 'Invalid JSON body' }), { status: 400, headers: corsHeaders });
  }

  const { session_id } = body;
  if (!session_id) {
    return new Response(JSON.stringify({ error: 'session_id required' }), { status: 400, headers: corsHeaders });
  }

  // Fetch session — must be owned by this requester
  const { data: session, error: sessionError } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq('id', session_id)
    .single();

  if (sessionError || !session) {
    return new Response(JSON.stringify({ error: 'Session not found' }), { status: 404, headers: corsHeaders });
  }

  if (session.requester_id !== user.id) {
    return new Response(JSON.stringify({ error: 'Forbidden' }), { status: 403, headers: corsHeaders });
  }

  // Must be payment_pending (shift ended) and not already paid
  if (!['payment_pending', 'completed'].includes(session.status)) {
    return new Response(JSON.stringify({ error: `Cannot refresh payment for session with status: ${session.status}` }), { status: 400, headers: corsHeaders });
  }

  if (session.status === 'requester_paid') {
    return new Response(JSON.stringify({ error: 'Session already paid' }), { status: 400, headers: corsHeaders });
  }

  // ── Read pricing_config for environment multiplier ──────────────────────────────
  const { data: pricingConfig } = await supabaseAdmin
    .from('pricing_config')
    .select('*')
    .maybeSingle();

  const envMultiplier = session.environment === 'Busy'
    ? (pricingConfig?.busy_multiplier ?? 1.5)
    : 1.0;

  // ── Fetch the base amount from the original payment_intent set by end-shift ────────
  // We look for the earliest non-expired intent for this session (the one end-shift created)
  const { data: existingIntents } = await supabaseAdmin
    .from('payment_intents')
    .select('*')
    .eq('session_id', session_id)
    .order('created_at', { ascending: true });

  // Base amount: use the first intent ever created for this session (end-shift's amount)
  // Fall back to session.total_cost if no intents exist
  const baseAmount = existingIntents && existingIntents.length > 0
    ? Number(existingIntents[0].amount_naira)
    : Number(session.total_cost ?? 0);

  // ── Calculate running total based on cycles elapsed since payment_initiated_at ─────
  const initiatedAt = session.payment_initiated_at
    ? new Date(session.payment_initiated_at).getTime()
    : Date.now();
  const now = Date.now();
  const cycleMs = 15 * 60 * 1000; // 15 minutes
  const cyclesElapsed = Math.floor((now - initiatedAt) / cycleMs);

  const hourlyRateNaira = (session.hourly_rate_kobo ?? 200000) / 100;
  const quarterHourRate = hourlyRateNaira * 0.25 * envMultiplier;
  const lateFeeNaira = cyclesElapsed * quarterHourRate;

  const newAmountNaira = Math.max(
    Math.ceil((baseAmount + lateFeeNaira) / 50) * 50,
    baseAmount
  );

  console.log(`[refresh-payment] session=${session_id} environment=${session.environment} envMultiplier=${envMultiplier} hourly_rate_kobo=${session.hourly_rate_kobo} baseAmount=${baseAmount} cyclesElapsed=${cyclesElapsed} quarterHourRate=${quarterHourRate} lateFeeNaira=${lateFeeNaira} newAmountNaira=${newAmountNaira}`);

  // ── Fetch pricing rules for split ──────────────────────────────────────────────
  const rules = await fetchPricingRules(supabaseAdmin);
  const { platformNaira, doctorNaira } = splitNaira(newAmountNaira, rules);

  // ── Fetch doctor profile for subaccount_code ──────────────────────────────────
  const { data: doctorProfile } = await supabaseAdmin
    .from('doctor_profiles')
    .select('subaccount_code')
    .eq('id', session.doctor_id)
    .maybeSingle();

  // ── Generate a brand-new Monnify reserved account for this cycle ───────────────
  let accountNumber: string;
  let bankName: string;
  let accountReference: string;
  let accountName: string;

  try {
    const newAccount = await reserveNewMonnifyAccount(
      session_id,
      session.doctor_id,
      doctorProfile?.subaccount_code,
      supabaseAdmin
    );
    accountNumber = newAccount.accountNumber;
    bankName = newAccount.bankName;
    accountReference = newAccount.accountReference;
    accountName = newAccount.accountName;
  } catch (monnifyErr: any) {
    console.error('[refresh-payment] Monnify reserve failed, falling back to existing account:', monnifyErr.message);
    // Fallback: use whatever is currently on the session
    accountNumber = session.monnify_account_number ?? '';
    bankName = session.monnify_bank_name ?? '';
    accountReference = session.monnify_account_reference ?? '';
    accountName = '';
  }

  const expiryAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();

  // ── Expire all existing pending payment_intents for this session ───────────────
  const { error: expireError } = await supabaseAdmin
    .from('payment_intents')
    .update({ status: 'expired', updated_at: new Date().toISOString() })
    .eq('session_id', session_id)
    .eq('status', 'pending');

  if (expireError) {
    console.error('[refresh-payment] Failed to expire old payment_intents:', expireError);
  }

  // ── Insert new payment_intent with updated amount and new account ──────────────
  const { data: paymentIntent, error: piError } = await supabaseAdmin
    .from('payment_intents')
    .insert({
      session_id: session_id,
      amount_naira: newAmountNaira,
      monnify_account_number: accountNumber,
      monnify_bank_name: bankName,
      monnify_account_reference: accountReference,
      status: 'pending',
      expiry_at: expiryAt,
    })
    .select()
    .single();

  if (piError || !paymentIntent) {
    console.error('[refresh-payment] Failed to insert payment_intent:', piError);
    return new Response(JSON.stringify({ error: 'Failed to create payment intent' }), { status: 500, headers: corsHeaders });
  }

  // ── Update coverage_sessions with new account details, new amount, and new deadline ──
  await supabaseAdmin
    .from('coverage_sessions')
    .update({
      monnify_account_reference: accountReference,
      monnify_account_number: accountNumber,
      monnify_bank_name: bankName,
      price: newAmountNaira,
      total_cost: newAmountNaira,
      payment_deadline_at: expiryAt,
      updated_at: new Date().toISOString(),
    })
    .eq('id', session_id);

  const paymentPayload = {
    id: paymentIntent.id,
    amount_naira: newAmountNaira,
    account_number: accountNumber,
    bank_name: bankName,
    account_reference: accountReference,
    expiry_at: expiryAt,
  };

  // Broadcast payment_refreshed on session channel
  await broadcastToChannel(`session:${session_id}`, 'payment_refreshed', { payment: paymentPayload });

  return new Response(JSON.stringify({
    success: true,
    payment: paymentPayload,
  }), {
    status: 200,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
