## 2b. `end-shift` — `_shared/billing.ts`

```typescript
// supabase/functions/_shared/billing.ts
// NAIRA-ONLY billing engine — no kobo anywhere in this file.

// ─── Types ───────────────────────────────────────────────────────────────────

export type PricingRules = {
  id: string;
  is_active: boolean;
  standard_min_floor_hours: number;
  standard_buffer_minutes: number;
  standard_block_minutes: number;
  standard_day_rate_short: number;   // < 4h booked  → ₦3,000/hr
  standard_day_rate_medium: number;  // 4–6h booked  → ₦2,500/hr
  standard_day_rate_long: number;    // > 6h booked  → ₦2,000/hr
  standard_night_rate: number;
  // Fix 3: Home Care always uses this flat hourly rate (₦15,000/hr),
  // bypassing all duration-bracket logic.
  home_care_rate: number;
  straight_24h_flat: number;
  straight_48h_flat: number;
  straight_72h_flat: number;
  straight_24h_lower: number;
  straight_24h_upper: number;
  straight_48h_lower: number;
  straight_48h_upper: number;
  straight_72h_lower: number;
  straight_72h_upper: number;
  straight_overage_rate_per_hour: number;
  platform_split_percent: number;
  doctor_split_percent: number;
  split_round_to: number;
};

export type BillingInput = {
  coverageType: string;
  shiftType: string;
  environment: string;
  bookedDurationSeconds: number;
  actualDurationSeconds: number;
  hourlyRateKobo: number;
  nightRateKobo?: number;
  busyMultiplier?: number;
  startHour?: number;
  straight24hFlatKobo?: number;
  straight48hFlatKobo?: number;
  straight72hFlatKobo?: number;
  straightOverageRateKobo?: number;
};

export type BillingResult = {
  billableSeconds: number;
  billableHours: number;
  amountKobo: number;
  amountNaira: number;
  label: string;
  mode: 'continuous' | 'segmented';
};

type LegacyRateConfig = {
  day_rate_short: number;
  day_rate_medium: number;
  day_rate_long: number;
  night_rate: number;
  home_care_rate: number;
  busy_multiplier?: number;
};

type SupabaseClient = {
  from: (table: string) => {
    select: (cols: string) => {
      eq: (col: string, val: unknown) => {
        single: () => Promise<{ data: unknown; error: unknown }>;
      };
    };
  };
};

export async function fetchPricingRules(supabaseClient: SupabaseClient): Promise<PricingRules> {
  const { data, error } = await (supabaseClient
    .from('pricing_rules')
    .select('*')
    .eq('is_active', true) as unknown as { single: () => Promise<{ data: PricingRules | null; error: unknown }> }).single();

  if (error || !data) {
    throw new Error('Failed to fetch pricing_rules: ' + JSON.stringify(error));
  }
  return data;
}

export type StandardBillingParams = {
  actualSeconds: number;
  bookedHours: number;
  hourlyRateNaira: number;
  rules: PricingRules;
};

export function calcStandardNaira(params: StandardBillingParams): number {
  const { actualSeconds, bookedHours, hourlyRateNaira, rules } = params;

  const floorSeconds = rules.standard_min_floor_hours * 3600;
  const bufferSeconds = rules.standard_buffer_minutes * 60;
  const blockSeconds = rules.standard_block_minutes * 60;
  const bookedSeconds = bookedHours * 3600;

  if (actualSeconds < floorSeconds) {
    return hourlyRateNaira * rules.standard_min_floor_hours;
  }

  if (Math.abs(actualSeconds - bookedSeconds) <= bufferSeconds) {
    return bookedHours * hourlyRateNaira;
  }

  const roundedSeconds = Math.ceil(actualSeconds / blockSeconds) * blockSeconds;
  return (roundedSeconds / 3600) * hourlyRateNaira;
}

export type StraightBillingParams = {
  actualSeconds: number;
  bookedHours: 24 | 48 | 72;
  rules: PricingRules;
};

export function calcStraightNaira(params: StraightBillingParams): number {
  const { actualSeconds, bookedHours, rules } = params;

  let flatFee: number;
  let lowerBound: number;
  let upperBound: number;

  if (bookedHours === 24) {
    flatFee = rules.straight_24h_flat;
    lowerBound = rules.straight_24h_lower;
    upperBound = rules.straight_24h_upper;
  } else if (bookedHours === 48) {
    flatFee = rules.straight_48h_flat;
    lowerBound = rules.straight_48h_lower;
    upperBound = rules.straight_48h_upper;
  } else {
    flatFee = rules.straight_72h_flat;
    lowerBound = rules.straight_72h_lower;
    upperBound = rules.straight_72h_upper;
  }

  const blockSeconds = rules.standard_block_minutes * 60;
  const lowerSeconds = lowerBound * 3600;
  const upperSeconds = upperBound * 3600;

  if (actualSeconds < 3600) {
    return flatFee / 24;
  }

  if (actualSeconds >= lowerSeconds && actualSeconds <= upperSeconds) {
    return flatFee;
  }

  if (actualSeconds > upperSeconds) {
    const extraSeconds = actualSeconds - upperSeconds;
    const roundedExtra = Math.ceil(extraSeconds / blockSeconds) * blockSeconds;
    return flatFee + (roundedExtra / 3600) * rules.straight_overage_rate_per_hour;
  }

  const roundedSeconds = Math.ceil(actualSeconds / blockSeconds) * blockSeconds;
  return (roundedSeconds / 3600) * rules.straight_overage_rate_per_hour;
}

export function splitNaira(
  totalNaira: number,
  rules: PricingRules
): { platformNaira: number; doctorNaira: number } {
  const platformNaira =
    Math.round((totalNaira * rules.platform_split_percent / 100) / rules.split_round_to) *
    rules.split_round_to;
  const doctorNaira = totalNaira - platformNaira;
  return { platformNaira, doctorNaira };
}

export function resolveHourlyRate(
  session: { shift_type?: string | null; coverage_type?: string | null; per_day_hours?: number | null },
  rules: PricingRules
): number {
  const shiftType = session.shift_type ?? '';
  const coverageType = session.coverage_type ?? '';

  if (
    shiftType === 'Home Care' ||
    coverageType === 'Home Care' ||
    coverageType.toLowerCase().includes('home care')
  ) {
    return rules.home_care_rate;
  }

  if (coverageType.toLowerCase().includes('night')) {
    return rules.standard_night_rate;
  }

  const durationHours = Number(session.per_day_hours ?? 8);
  if (durationHours < 4) {
    return rules.standard_day_rate_short;
  } else if (durationHours <= 6) {
    return rules.standard_day_rate_medium;
  } else {
    return rules.standard_day_rate_long;
  }
}

const STRAIGHT_COVERAGE_TYPES = ['Straight 24h', 'Straight 48h', 'Straight 72h'];

export function isStraightCoverage(coverageType: string): boolean {
  return STRAIGHT_COVERAGE_TYPES.some(
    t => coverageType.toLowerCase().includes(t.toLowerCase()) || coverageType === t
  );
}

export function isStraightBooking(
  coverageType: string,
  startTime?: string,
  endTime?: string
): boolean {
  if (isStraightCoverage(coverageType)) return true;
  if (startTime && endTime && startTime.trim() === endTime.trim()) return true;
  return false;
}

export function resolveEffectiveCoverageType(
  coverageType: string,
  coverageLength: number,
  startTime?: string,
  endTime?: string
): string {
  if (isStraightBooking(coverageType, startTime, endTime)) {
    if (coverageLength >= 3) return 'Straight 72h';
    if (coverageLength >= 2) return 'Straight 48h';
    return 'Straight 24h';
  }
  return coverageType;
}

export function resolveHourlyRateKobo(
  shiftType: string,
  coverageType: string,
  durationHours: number,
  config: LegacyRateConfig
): number {
  if (shiftType === 'Home Care' || coverageType === 'Home Care') {
    return Math.round(config.home_care_rate * 100);
  }
  if (coverageType.toLowerCase().includes('night')) {
    return Math.round(config.night_rate * 100);
  }
  if (durationHours < 4) {
    return Math.round(config.day_rate_short * 100);
  } else if (durationHours <= 6) {
    return Math.round(config.day_rate_medium * 100);
  } else {
    return Math.round(config.day_rate_long * 100);
  }
}

function formatLabel(seconds: number): string {
  const totalMinutes = Math.round(seconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  if (minutes === 0) return `${hours}hr 00min`;
  return `${hours}hr ${String(minutes).padStart(2, '0')}min`;
}

export function buildCoverageLabel(
  coverageType: string,
  totalHours: number,
  coverageLength: number
): string {
  const h = Math.round(totalHours);
  if (coverageType === 'Straight 24h' || coverageType.toLowerCase().includes('straight 24')) {
    return '24-hour Straight Coverage';
  }
  if (coverageType === 'Straight 48h' || coverageType.toLowerCase().includes('straight 48')) {
    return '48-hour Straight Coverage';
  }
  if (coverageType === 'Straight 72h' || coverageType.toLowerCase().includes('straight 72')) {
    return '72-hour Straight Coverage';
  }
  if (coverageLength > 1) {
    return `${h}-hour Multi-Day Coverage (${coverageLength} days)`;
  }
  return `${h}-hour Single-Day Coverage`;
}

function getEnvironmentMultiplier(shiftType: string, environment: string, busyMultiplier = 1.3): number {
  if (shiftType === 'Home Care') return 1.0;
  if (environment === 'Busy') return busyMultiplier;
  return 1.0;
}

function calcSegmented(input: BillingInput): BillingResult {
  const {
    actualDurationSeconds, bookedDurationSeconds, hourlyRateKobo,
    nightRateKobo, shiftType, environment, busyMultiplier = 1.3, startHour,
  } = input;

  const GRACE_SECONDS = 900;
  const BLOCK_SECONDS = 900;
  const MIN_SECONDS = 3600;

  const diff = Math.abs(actualDurationSeconds - bookedDurationSeconds);
  let billableSeconds: number;

  if (diff <= GRACE_SECONDS) {
    billableSeconds = bookedDurationSeconds;
  } else {
    billableSeconds = Math.ceil(actualDurationSeconds / BLOCK_SECONDS) * BLOCK_SECONDS;
  }
  billableSeconds = Math.max(billableSeconds, MIN_SECONDS);

  const multiplier = getEnvironmentMultiplier(shiftType, environment, busyMultiplier);
  const billableHours = billableSeconds / 3600;

  let amountKobo: number;

  if (startHour !== undefined && nightRateKobo !== undefined && nightRateKobo > 0 &&
      shiftType !== 'Home Care') {
    const DAY_START = 6;
    const DAY_END = 22;
    const shiftEndHour = startHour + billableHours;
    const dayOverlapStart = Math.max(startHour, DAY_START);
    const dayOverlapEnd = Math.min(shiftEndHour, DAY_END);
    const dayHours = Math.max(0, dayOverlapEnd - dayOverlapStart);
    const nightHours = Math.max(0, billableHours - dayHours);
    amountKobo = Math.round((dayHours * hourlyRateKobo + nightHours * nightRateKobo) * multiplier);
  } else {
    amountKobo = Math.round(billableHours * hourlyRateKobo * multiplier);
  }

  return {
    billableSeconds,
    billableHours,
    amountKobo,
    amountNaira: amountKobo / 100,
    label: formatLabel(billableSeconds),
    mode: 'segmented',
  };
}

function calcContinuous(input: BillingInput): BillingResult {
  const {
    actualDurationSeconds,
    bookedDurationSeconds,
    hourlyRateKobo,
    shiftType,
    environment,
    straight24hFlatKobo = 3600000,
    straight48hFlatKobo = 7200000,
    straight72hFlatKobo = 10800000,
    straightOverageRateKobo = 150000,
  } = input;

  const actualHours = actualDurationSeconds / 3600;
  const multiplier = getEnvironmentMultiplier(shiftType, environment, input.busyMultiplier ?? 1.3);
  const bookedHours = bookedDurationSeconds / 3600;

  let flatKobo: number;
  let lowerBound: number;
  let upperBound: number;

  if (bookedHours <= 26) {
    flatKobo = straight24hFlatKobo;
    lowerBound = 22;
    upperBound = 25;
  } else if (bookedHours <= 50) {
    flatKobo = straight48hFlatKobo;
    lowerBound = 46;
    upperBound = 49;
  } else {
    flatKobo = straight72hFlatKobo;
    lowerBound = 70;
    upperBound = 73;
  }

  let amountKobo: number;
  let billableSeconds: number;

  if (actualHours <= upperBound) {
    amountKobo = Math.round(flatKobo * multiplier);
    billableSeconds = lowerBound * 3600;
  } else {
    const overageHours = actualHours - upperBound;
    const overageKobo = overageHours * straightOverageRateKobo;
    amountKobo = Math.round((flatKobo + overageKobo) * multiplier);
    billableSeconds = actualDurationSeconds;
  }

  const billableHours = billableSeconds / 3600;

  return {
    billableSeconds,
    billableHours,
    amountKobo,
    amountNaira: amountKobo / 100,
    label: formatLabel(billableSeconds),
    mode: 'continuous',
  };
}

export function calculateBill(input: BillingInput): BillingResult {
  if (isStraightCoverage(input.coverageType)) {
    return calcContinuous(input);
  }
  return calcSegmented(input);
}
