```typescript
import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { getAuthenticatedUser, getServiceClient } from './auth.ts';
import { set, zrem, KEYS } from './redis.ts';
import { broadcastToChannel } from './broadcast.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function computeHourlyRateKobo(
  shiftType: string,
  startTime: string | null,
  bookedSeconds: number
): number {
  if (shiftType === 'Home Care') return 1500000;
  if (startTime) {
    const [h] = startTime.split(':').map(Number);
    if (h >= 22 || h < 6) return 150000;
  }
  const bookedHours = bookedSeconds / 3600;
  if (bookedHours < 4) return 300000;
  if (bookedHours <= 6) return 250000;
  return 200000;
}

function timeToSeconds(t: string): number {
  const parts = t.split(':').map(Number);
  return (parts[0] ?? 0) * 3600 + (parts[1] ?? 0) * 60 + (parts[2] ?? 0);
}

function normaliseTime(t: string): string {
  return t.slice(0, 5);
}

function toTitleCase(str: string): string {
  return str
    .toLowerCase()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

function isAllCaps(str: string): boolean {
  const letters = str.replace(/[^a-zA-Z]/g, '');
  return letters.length > 0 && letters === letters.toUpperCase();
}

function stripDrPrefix(name: string): string {
  return name.replace(/^dr\.?\s*/i, '').trim();
}

function toDateString(value: string | null | undefined): string | null {
  if (!value) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
  return value.split('T')[0] ?? null;
}

function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const user = await getAuthenticatedUser(req);
    const doctorId = user.id;

    const body = await req.json();
    const { request_id } = body;

    if (!request_id) {
      return new Response(
        JSON.stringify({ error: 'Missing required field: request_id' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const serviceClient = getServiceClient();

    const { data: existingRequest, error: fetchError } = await serviceClient
      .from('coverage_requests')
      .select('id, status, requester_id, hospital_name, hospital_address, shift_date, start_date, end_date, start_time, end_time, shift_type, coverage_type, environment, price, coverage_length, per_day_hours')
      .eq('id', request_id)
      .single();

    if (fetchError || !existingRequest) {
      return new Response(
        JSON.stringify({ error: 'Request not found', detail: fetchError?.message }),
        { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    if (existingRequest.status !== 'pending') {
      return new Response(
        JSON.stringify({ error: 'ALREADY_MATCHED', message: 'This request is no longer available.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // --- Guard A: 3-job cap ---
    const { count: activeCount, error: capError } = await serviceClient
      .from('coverage_sessions')
      .select('id', { count: 'exact', head: true })
      .eq('doctor_id', doctorId)
      .in('status', ['upcoming', 'active', 'paused']);

    if (capError) throw new Error(`Cap check failed: ${capError.message}`);

    if ((activeCount ?? 0) >= 3) {
      return new Response(
        JSON.stringify({ error: 'CAP_REACHED', message: 'Max shifts reached' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // --- Guard B: time-overlap conflict check using shift_start / shift_end ---
    const rawShiftDateForConflict = existingRequest.shift_date
      ?? toDateString(existingRequest.start_date)
      ?? null;
    const incomingStartISO: string | null = rawShiftDateForConflict && existingRequest.start_time
      ? `${rawShiftDateForConflict}T${normaliseTime(existingRequest.start_time)}:00`
      : (existingRequest.start_date ?? null);
    const incomingEndISO: string | null = rawShiftDateForConflict && existingRequest.end_time
      ? `${rawShiftDateForConflict}T${normaliseTime(existingRequest.end_time)}:00`
      : (existingRequest.end_date ?? null);

    if (incomingStartISO && incomingEndISO) {
      const { data: existingSessions, error: sessionsError } = await serviceClient
        .from('coverage_sessions')
        .select('shift_start, shift_end')
        .eq('doctor_id', doctorId)
        .in('status', ['upcoming', 'active', 'paused']);

      if (sessionsError) throw new Error(`Conflict check failed: ${sessionsError.message}`);

      if (existingSessions && existingSessions.length > 0) {
        const incomingStart = new Date(incomingStartISO).getTime();
        const incomingEnd = new Date(incomingEndISO).getTime();

        for (const s of existingSessions) {
          if (!s.shift_start || !s.shift_end) continue;
          const existingStart = new Date(s.shift_start as string).getTime();
          const existingEnd = new Date(s.shift_end as string).getTime();
          // Standard interval overlap
          if (incomingStart < existingEnd && incomingEnd > existingStart) {
            return new Response(
              JSON.stringify({ error: 'SHIFT_CONFLICT', message: 'Shift conflict' }),
              { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
            );
          }
        }
      }
    }

    // --- Race-condition lock ---
    const lockResult = await set(KEYS.lock(request_id), doctorId, { ex: 10, nx: true });

    if (lockResult === null) {
      return new Response(
        JSON.stringify({ error: 'RACE_LOST', message: 'Another doctor accepted this request first.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const now = new Date().toISOString();
    const { data: updatedRows, error: updateError } = await serviceClient
      .from('coverage_requests')
      .update({
        status: 'matched',
        matched_doctor_id: doctorId,
        matched_at: now,
        updated_at: now,
      })
      .eq('id', request_id)
      .eq('status', 'pending')
      .select('id');

    if (updateError) throw new Error(`DB update failed: ${updateError.message}`);

    if (!updatedRows || updatedRows.length === 0) {
      return new Response(
        JSON.stringify({ error: 'ALREADY_MATCHED', message: 'Request was matched by another doctor.' }),
        { status: 409, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    await zrem(KEYS.REQUEST_QUEUE, request_id);

    const requesterId = existingRequest.requester_id;

    const [
      { data: doctorProfile, error: dpError },
      { data: doctorDetails, error: ddError },
      { data: requesterProfileRaw },
      { data: { user: doctorAuthUser } },
    ] = await Promise.all([
      serviceClient
        .from('profiles')
        .select('full_name, first_name, last_name, phone')
        .eq('id', doctorId)
        .single(),
      serviceClient
        .from('doctor_profiles')
        .select('mdcn_number, rating, reliability_score, account_name, selfie_url')
        .eq('id', doctorId)
        .single(),
      serviceClient
        .from('profiles')
        .select('first_name, last_name, phone, rating')
        .eq('id', requesterId)
        .single(),
      serviceClient.auth.admin.getUserById(doctorId),
    ]);

    const requesterProfile = requesterProfileRaw;

    // Resolve requester rating from their profile
    const requesterRating = requesterProfile?.rating ?? null;

    const authFullName = (doctorAuthUser?.user_metadata?.full_name as string | undefined | null) ?? null;

    console.log('[accept-request] doctorProfile:', JSON.stringify(doctorProfile), 'error:', dpError?.message);
    console.log('[accept-request] doctorDetails:', JSON.stringify(doctorDetails), 'error:', ddError?.message);
    console.log('[accept-request] requesterProfile:', JSON.stringify(requesterProfile));
    console.log('[accept-request] authFullName:', authFullName);
    console.log('[accept-request] requesterRating:', requesterRating);

    let doctorName: string;

    const firstName = (doctorProfile?.first_name ?? '').trim();
    const lastName = (doctorProfile?.last_name ?? '').trim();

    if (firstName && lastName) {
      const combined = `${firstName} ${lastName}`;
      const displayName = isAllCaps(combined) ? toTitleCase(combined) : combined;
      doctorName = stripDrPrefix(displayName);
    } else if (authFullName && authFullName.trim()) {
      const trimmed = authFullName.trim();
      const displayName = isAllCaps(trimmed) ? toTitleCase(trimmed) : trimmed;
      doctorName = stripDrPrefix(displayName);
    } else {
      const fullName = (doctorProfile?.full_name ?? '').trim();
      if (fullName) {
        const displayName = isAllCaps(fullName) ? toTitleCase(fullName) : fullName;
        doctorName = stripDrPrefix(displayName);
      } else if (doctorDetails?.account_name && doctorDetails.account_name.trim()) {
        const stripped = doctorDetails.account_name.trim().replace(/^DR\.?\s*/i, '');
        doctorName = toTitleCase(stripped);
      } else {
        doctorName = stripDrPrefix(user.email?.split('@')[0] ?? 'Doctor');
      }
    }

    console.log('[accept-request] doctorName resolved to (no Dr. prefix):', doctorName);

    let doctorAvatar: string | null = null;
    if (doctorDetails?.selfie_url) {
      const { data: signedData, error: signError } = await serviceClient
        .storage
        .from('doctor-documents')
        .createSignedUrl(doctorDetails.selfie_url, 60 * 60 * 24 * 7);
      if (signError) {
        console.error('[accept-request] Failed to sign selfie URL:', signError.message);
        doctorAvatar = null;
      } else {
        doctorAvatar = signedData?.signedUrl ?? null;
      }
    }

    console.log('[accept-request] doctorAvatar:', doctorAvatar ? 'signed URL obtained' : 'null');

    const doctorPayload = {
      name: `Dr. ${doctorName}`,
      mdcn: doctorDetails?.mdcn_number ?? 'MDCN/R/00000',
      rating: doctorDetails?.rating ?? 5.0,
      reliability: doctorDetails?.reliability_score ?? 100,
    };

    await Promise.all([
      broadcastToChannel(
        `requester:${request_id}`,
        'MATCH_CONFIRMED',
        { doctor: doctorPayload }
      ),
      broadcastToChannel(
        'dispatch:lagos',
        'EVICT_REQUEST',
        { request_id }
      ),
    ]);

    const reqStartDate = existingRequest.start_date ?? null;
    const reqEndDate = existingRequest.end_date ?? null;

    const startTimeSec = existingRequest.start_time
      ? timeToSeconds(existingRequest.start_time)
      : (reqStartDate ? new Date(reqStartDate).getHours() * 3600 + new Date(reqStartDate).getMinutes() * 60 : 0);
    const endTimeSec = existingRequest.end_time
      ? timeToSeconds(existingRequest.end_time)
      : (reqEndDate ? new Date(reqEndDate).getHours() * 3600 + new Date(reqEndDate).getMinutes() * 60 : 0);

    let bookedSeconds = endTimeSec - startTimeSec;
    if (bookedSeconds <= 0) bookedSeconds += 86400;

    const startTimeStr = existingRequest.start_time ?? null;
    const hourlyRateKobo = computeHourlyRateKobo(
      existingRequest.shift_type ?? 'Standard',
      startTimeStr,
      bookedSeconds
    );

    const incomingCoverageLength = typeof existingRequest.coverage_length === 'number'
      ? existingRequest.coverage_length
      : (existingRequest.coverage_length != null ? parseInt(existingRequest.coverage_length, 10) : 1);
    const coverageLength = incomingCoverageLength;

    const environment = existingRequest.environment ?? 'Normal';
