    const rawShiftDate = existingRequest.shift_date ?? reqStartDate?.split('T')[0] ?? null;
    const shiftDate = toDateString(rawShiftDate);

    const shiftStartISO = shiftDate && existingRequest.start_time
      ? `${shiftDate}T${normaliseTime(existingRequest.start_time)}:00+01:00`
      : (reqStartDate ?? null);
    const shiftEndISO = shiftDate && existingRequest.end_time
      ? `${shiftDate}T${normaliseTime(existingRequest.end_time)}:00+01:00`
      : (reqEndDate ?? null);

    console.log('[accept-request] shiftDate:', shiftDate, 'shiftStartISO:', shiftStartISO, 'shiftEndISO:', shiftEndISO, 'coverageLength:', coverageLength);

    const doctorPhone = doctorProfile?.phone ?? null;
    const requesterPhone = requesterProfile?.phone ?? null;

    console.log('[accept-request] doctorPhone:', doctorPhone, 'requesterPhone:', requesterPhone);

    const sessionData = {
