content = content.replace(/\{\s*console\.(log|warn|error)\([^)]*(?:\([^)]*\)[^)]*)*\);\s*/g, '{ ');

// Pattern 2: .then(() => console.log(...)) — remove the whole .then(...)
content = content.replace(/\s*\.then\(\(\)\s*=>\s*console\.(log|warn|error)\([^)]*(?:\([^)]*\)[^)]*)*\)\)/g, '');

// Pattern 3: onMapReady={() => console.log(...)} — replace with onMapReady={() => {}}
content = content.replace(/onMapReady=\{[^}]*console\.(log|warn|error)\([^)]*\)[^}]*\}/g, 'onMapReady={() => {}}');

const remaining = (content.match(/console\.(log|warn|error)/g) || []).length;
console.log('Remaining console statements:', remaining);

fs.writeFileSync('/tmp/index_final.tsx', content);
