// Simple module-level in-memory cache for tab data
// Persists across component unmounts (unlike useState)

type CacheEntry<T> = { data: T; fetchedAt: number };
const cache = new Map<string, CacheEntry<unknown>>();

export const STALE_MS = 30_000; // 30 seconds

export function getCached<T>(key: string): T | null {
  const entry = cache.get(key) as CacheEntry<T> | undefined;
  if (!entry) return null;
  return entry.data;
}

export function setCached<T>(key: string, data: T): void {
  cache.set(key, { data, fetchedAt: Date.now() });
}

export function isStale(key: string): boolean {
  const entry = cache.get(key);
  if (!entry) return true;
  return Date.now() - entry.fetchedAt > STALE_MS;
}

export function invalidate(key: string): void {
  cache.delete(key);
}

export function clearAll(): void {
  console.log('[tabCache] clearAll — wiping all cached tab data');
  cache.clear();
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { getCached, setCached, isStale } from '@/utils/tabCache';

interface UseTabDataOptions<T> {
  cacheKey: string;
  fetcher: () => Promise<T>;
  /** If true, always refetch in background even if cache is fresh. Default false. */
  alwaysRefresh?: boolean;
}

interface UseTabDataResult<T> {
  data: T | null;
  loading: boolean;      // true ONLY on first load (no cached data)
  refreshing: boolean;   // true during background refresh (cached data visible)
  error: string | null;
  refresh: () => void;
}

export function useTabData<T>({
  cacheKey,
  fetcher,
  alwaysRefresh = false,
}: UseTabDataOptions<T>): UseTabDataResult<T> {
  const cached = getCached<T>(cacheKey);
  const [data, setData] = useState<T | null>(cached);
  const [loading, setLoading] = useState(cached === null);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const doFetch = useCallback(
    async (isBackground: boolean) => {
      if (isBackground) setRefreshing(true);
      else setLoading(true);
      setError(null);
      try {
        const result = await fetcher();
        if (!mountedRef.current) return;
        setCached(cacheKey, result);
        setData(result);
      } catch (e: unknown) {
        if (!mountedRef.current) return;
        const msg = e instanceof Error ? e.message : 'Failed to load';
        setError(msg);
      } finally {
        if (mountedRef.current) {
          setLoading(false);
          setRefreshing(false);
        }
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [cacheKey, fetcher],
  );

  useEffect(() => {
    const hasCache = getCached(cacheKey) !== null;
    const stale = isStale(cacheKey);
    if (!hasCache) {
      doFetch(false); // first load — show spinner
    } else if (stale || alwaysRefresh) {
      doFetch(true);  // background refresh — keep showing cached data
    }
    // If cache is fresh and alwaysRefresh=false, do nothing
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [cacheKey]);

  const refresh = useCallback(() => {
    const hasCache = getCached(cacheKey) !== null;
    doFetch(!hasCache);
  }, [cacheKey, doFetch]);

  return { data, loading, refreshing, error, refresh };
}

