**`_shared/billing.ts`:**
```typescript
// _shared/billing.ts
// Single source of truth for all billing logic.
// All values come from the pricing_rules table — no hardcoded constants.

export type PricingRules = {
  id: string;
  is_active: boolean;
  standard_min_floor_hours: number;
  standard_buffer_minutes: number;
  standard_block_minutes: number;
  standard_day_rate_short: number;
  standard_day_rate_medium: number;
  standard_day_rate_long: number;
  standard_night_rate: number;
  home_care_rate: number;
  busy_multiplier: number;
  straight_24h_flat: number;
  straight_48h_flat: number;
  straight_72h_flat: number;
  straight_24h_lower: number;
  straight_24h_upper: number;
  straight_48h_lower: number;
  straight_48h_upper: number;
  straight_72h_lower: number;
  straight_72h_upper: number;
  straight_overage_rate_per_hour: number;
  platform_split_percent: number;
  doctor_split_percent: number;
  split_round_to: number;
};

export type BillingInput = {
  coverageType: string;
  shiftType: string;
  environment: string;
  bookedDurationSeconds: number;
  actualDurationSeconds: number;
  startHour?: number;
  rules: PricingRules;
};

export type BillingResult = {
  billableSeconds: number;
  billableHours: number;
  amountNaira: number;
  mode: 'segmented' | 'continuous';
  label: string;
};

export type SplitResult = {
  platformNaira: number;
  doctorNaira: number;
};

export function isStraightCoverage(coverageType: string): boolean {
  return ['straight 24h', 'straight 48h', 'straight 72h'].some(
    t => coverageType.toLowerCase().includes(t)
  );
}

export function resolveEffectiveCoverageType(
  coverageType: string,
  coverageLength: number,
  startTime?: string,
  endTime?: string
): string {
  const isStraight =
    isStraightCoverage(coverageType) ||
    (startTime != null && endTime != null && startTime.trim() === endTime.trim());
  if (isStraight) {
    if (coverageLength >= 3) return 'Straight 72h';
    if (coverageLength >= 2) return 'Straight 48h';
    return 'Straight 24h';
  }
  return coverageType;
}

export function resolveHourlyRate(
  shiftType: string,
  coverageType: string,
  durationHours: number,
  rules: PricingRules
): number {
  if (shiftType === 'Home Care' || coverageType.toLowerCase().includes('home care')) {
    return rules.home_care_rate;
  }
  if (coverageType.toLowerCase().includes('night')) {
    return rules.standard_night_rate;
  }
  if (durationHours < 4) return rules.standard_day_rate_short;
  if (durationHours <= 6) return rules.standard_day_rate_medium;
  return rules.standard_day_rate_long;
}

export function resolveHourlyRateFromSession(
  session: { shift_type?: string | null; coverage_type?: string | null; per_day_hours?: number | null },
  rules: PricingRules
): number {
  const coverageType = session.coverage_type ?? '';
  const durationHours = Number(session.per_day_hours ?? 8);

  if (coverageType.toLowerCase().includes('night')) {
    return rules.standard_night_rate;
  }
  if (durationHours < 4) {
    return rules.standard_day_rate_short;
  } else if (durationHours <= 6) {
    return rules.standard_day_rate_medium;
  } else {
    return rules.standard_day_rate_long;
  }
}

function getEnvironmentMultiplier(shiftType: string, environment: string, rules: PricingRules): number {
  if (shiftType === 'Home Care') return 1.0;
  if (environment === 'Busy') return rules.busy_multiplier;
  return 1.0;
}

function formatLabel(seconds: number): string {
  const totalMinutes = Math.round(seconds / 60);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return minutes === 0 ? `${hours}hr 00min` : `${hours}hr ${String(minutes).padStart(2, '0')}min`;
}

export function buildCoverageLabel(coverageType: string, totalHours: number, coverageLength: number): string {
  const h = Math.round(totalHours);
  if (coverageType.toLowerCase().includes('straight 24')) return '24-hour Straight Coverage';
  if (coverageType.toLowerCase().includes('straight 48')) return '48-hour Straight Coverage';
  if (coverageType.toLowerCase().includes('straight 72')) return '72-hour Straight Coverage';
  if (coverageLength > 1) return `${h}-hour Multi-Day Coverage (${coverageLength} days)`;
  return `${h}-hour Single-Day Coverage`;
}

export type StandardBillingParams = {
  actualSeconds: number;
  bookedHours: number;
  hourlyRateNaira: number;
  rules: PricingRules;
};

export function calcStandardNaira(params: StandardBillingParams): number {
  const { actualSeconds, bookedHours, hourlyRateNaira, rules } = params;

  const floorSeconds = rules.standard_min_floor_hours * 3600;
  const bufferSeconds = rules.standard_buffer_minutes * 60;
  const blockSeconds = rules.standard_block_minutes * 60;
  const bookedSeconds = bookedHours * 3600;

  if (actualSeconds < floorSeconds) {
    return hourlyRateNaira * rules.standard_min_floor_hours;
  }

  if (Math.abs(actualSeconds - bookedSeconds) <= bufferSeconds) {
    return bookedHours * hourlyRateNaira;
  }

  const roundedSeconds = Math.ceil(actualSeconds / blockSeconds) * blockSeconds;
  return (roundedSeconds / 3600) * hourlyRateNaira;
}

export type StraightBillingParams = {
  actualSeconds: number;
  bookedHours: 24 | 48 | 72;
  rules: PricingRules;
};

export function calcStraightNaira(params: StraightBillingParams): number {
  const { actualSeconds, bookedHours, rules } = params;

  let flatFee: number;
  let lowerBound: number;
  let upperBound: number;

  if (bookedHours === 24) {
    flatFee = rules.straight_24h_flat;
    lowerBound = rules.straight_24h_lower;
    upperBound = rules.straight_24h_upper;
  } else if (bookedHours === 48) {
    flatFee = rules.straight_48h_flat;
    lowerBound = rules.straight_48h_lower;
    upperBound = rules.straight_48h_upper;
  } else {
    flatFee = rules.straight_72h_flat;
    lowerBound = rules.straight_72h_lower;
    upperBound = rules.straight_72h_upper;
  }

  const blockSeconds = rules.standard_block_minutes * 60;
  const lowerSeconds = lowerBound * 3600;
  const upperSeconds = upperBound * 3600;

  if (actualSeconds < 3600) {
    return flatFee / 24;
  }

  if (actualSeconds >= lowerSeconds && actualSeconds <= upperSeconds) {
    return flatFee;
  }

  if (actualSeconds > upperSeconds) {
    const extraSeconds = actualSeconds - upperSeconds;
    const roundedExtra = Math.ceil(extraSeconds / blockSeconds) * blockSeconds;
    return flatFee + (roundedExtra / 3600) * rules.straight_overage_rate_per_hour;
  }

  const roundedSeconds = Math.ceil(actualSeconds / blockSeconds) * blockSeconds;
  return (roundedSeconds / 3600) * rules.straight_overage_rate_per_hour;
}

function calcSegmented(input: BillingInput, hourlyRate: number): BillingResult {
  const { actualDurationSeconds, bookedDurationSeconds, shiftType, environment, startHour, rules } = input;

  const graceSeconds = rules.standard_buffer_minutes * 60;
  const blockSeconds = rules.standard_block_minutes * 60;
  const floorSeconds = rules.standard_min_floor_hours * 3600;

  const diff = Math.abs(actualDurationSeconds - bookedDurationSeconds);
  let billableSeconds: number;

  if (actualDurationSeconds < floorSeconds) {
    billableSeconds = floorSeconds;
  } else if (diff <= graceSeconds) {
    billableSeconds = bookedDurationSeconds;
  } else {
    billableSeconds = Math.ceil(actualDurationSeconds / blockSeconds) * blockSeconds;
  }
  billableSeconds = Math.max(billableSeconds, floorSeconds);

  const multiplier = getEnvironmentMultiplier(shiftType, environment, rules);
  const billableHours = billableSeconds / 3600;

  let amountNaira: number;

  if (startHour !== undefined && shiftType !== 'Home Care' && !input.coverageType.toLowerCase().includes('home care')) {
    const DAY_START = 6;
    const DAY_END = 22;
    const shiftEndHour = startHour + billableHours;
    const dayHours = Math.max(0, Math.min(shiftEndHour, DAY_END) - Math.max(startHour, DAY_START));
    const nightHours = Math.max(0, billableHours - dayHours);
    amountNaira = (dayHours * hourlyRate + nightHours * rules.standard_night_rate) * multiplier;
  } else {
    amountNaira = billableHours * hourlyRate * multiplier;
  }

  amountNaira = Math.ceil(amountNaira / 50) * 50;

  return {
    billableSeconds,
    billableHours,
    amountNaira,
    mode: 'segmented',
    label: formatLabel(billableSeconds),
  };
}

function calcContinuous(input: BillingInput): BillingResult {
  const { actualDurationSeconds, bookedDurationSeconds, shiftType, environment, rules } = input;

  const blockSeconds = rules.standard_block_minutes * 60;
  const multiplier = getEnvironmentMultiplier(shiftType, environment, rules);
  const bookedHours = bookedDurationSeconds / 3600;
  const actualHours = actualDurationSeconds / 3600;

  let flatFee: number;
  let lowerBound: number;
  let upperBound: number;

  if (bookedHours <= 26) {
    flatFee = rules.straight_24h_flat;
    lowerBound = rules.straight_24h_lower;
    upperBound = rules.straight_24h_upper;
  } else if (bookedHours <= 50) {
    flatFee = rules.straight_48h_flat;
    lowerBound = rules.straight_48h_lower;
    upperBound = rules.straight_48h_upper;
  } else {
    flatFee = rules.straight_72h_flat;
    lowerBound = rules.straight_72h_lower;
    upperBound = rules.straight_72h_upper;
  }

  let amountNaira: number;
  let billableSeconds: number;

  const perHourRate = flatFee / bookedHours;
  if (actualHours < lowerBound) {
    amountNaira = Math.ceil((actualHours * perHourRate * multiplier) / 50) * 50;
    billableSeconds = actualDurationSeconds;
  } else if (actualHours <= upperBound) {
    amountNaira = Math.ceil((flatFee * multiplier) / 50) * 50;
    billableSeconds = lowerBound * 3600;
  } else {
    const overageHours = actualHours - upperBound;
    const roundedOverageSeconds = Math.ceil((overageHours * 3600) / blockSeconds) * blockSeconds;
    const overageNaira = (roundedOverageSeconds / 3600) * perHourRate;
    amountNaira = Math.ceil(((flatFee + overageNaira) * multiplier) / 50) * 50;
    billableSeconds = actualDurationSeconds;
  }

  return {
    billableSeconds,
    billableHours: billableSeconds / 3600,
    amountNaira,
    mode: 'continuous',
    label: formatLabel(billableSeconds),
  };
}

export function calculateBill(input: BillingInput): BillingResult {
  if (isStraightCoverage(input.coverageType)) {
    return calcContinuous(input);
  }
  const hourlyRate = resolveHourlyRate(
    input.shiftType,
    input.coverageType,
    input.bookedDurationSeconds / 3600,
    input.rules
  );
  return calcSegmented(input, hourlyRate);
}

export function splitNaira(totalNaira: number, rules: PricingRules): SplitResult {
  const platformNaira =
    Math.round((totalNaira * rules.platform_split_percent / 100) / rules.split_round_to) *
    rules.split_round_to;
  return { platformNaira, doctorNaira: totalNaira - platformNaira };
}

export async function fetchPricingRules(supabaseClient: any): Promise<PricingRules> {
  const { data, error } = await supabaseClient
    .from('pricing_rules')
    .select('*')
    .eq('is_active', true)
    .single();
  if (error || !data) throw new Error('Failed to fetch pricing_rules: ' + JSON.stringify(error));
  return data as PricingRules;
}
