    ] = await Promise.all([
      serviceClient
        .from('profiles')
        .select('full_name, first_name, last_name, phone')
        .eq('id', doctorId)
        .single(),
      serviceClient
        .from('doctor_profiles')
        .select('mdcn_number, rating, reliability_score, account_name, selfie_url')
        .eq('id', doctorId)
        .single(),
      serviceClient
        .from('profiles')
        .select('first_name, last_name, phone')
        .eq('id', requesterId)
        .single(),
      serviceClient
        .from('requester_profiles')
        .select('rating')
        .eq('id', requesterId)
        .maybeSingle(),
      serviceClient.auth.admin.getUserById(doctorId),
    ]);

    const requesterProfile = requesterProfileRaw;
    const authFullName = (doctorAuthUser?.user_metadata?.full_name as string | undefined | null) ?? null;

    console.log('[accept-request] doctorProfile:', JSON.stringify(doctorProfile), 'error:', dpError?.message);
    console.log('[accept-request] doctorDetails:', JSON.stringify(doctorDetails), 'error:', ddError?.message);
    console.log('[accept-request] requesterProfile:', JSON.stringify(requesterProfile));
    console.log('[accept-request] requesterDetails:', JSON.stringify(requesterDetails));
    console.log('[accept-request] authFullName:', authFullName);

    let doctorName: string;

    const firstName = (doctorProfile?.first_name ?? '').trim();
    const lastName = (doctorProfile?.last_name ?? '').trim();

    if (firstName && lastName) {
      const combined = `${firstName} ${lastName}`;
      const displayName = isAllCaps(combined) ? toTitleCase(combined) : combined;
      doctorName = stripDrPrefix(displayName);
    } else if (authFullName && authFullName.trim()) {
      const trimmed = authFullName.trim();
      const displayName = isAllCaps(trimmed) ? toTitleCase(trimmed) : trimmed;
      doctorName = stripDrPrefix(displayName);
    } else {
      const fullName = (doctorProfile?.full_name ?? '').trim();
      if (fullName) {
        const displayName = isAllCaps(fullName) ? toTitleCase(fullName) : fullName;
        doctorName = stripDrPrefix(displayName);
      } else if (doctorDetails?.account_name && doctorDetails.account_name.trim()) {
        const stripped = doctorDetails.account_name.trim().replace(/^DR\.?\s*/i, '');
        doctorName = toTitleCase(stripped);
      } else {
        doctorName = stripDrPrefix(user.email?.split('@')[0] ?? 'Doctor');
      }
    }

    console.log('[accept-request] doctorName resolved to (no Dr. prefix):', doctorName);

    let doctorAvatar: string | null = null;
    if (doctorDetails?.selfie_url) {
      const { data: signedData, error: signError } = await serviceClient
        .storage
        .from('doctor-documents')
        .createSignedUrl(doctorDetails.selfie_url, 60 * 60 * 24 * 7);
      if (signError) {
        console.error('[accept-request] Failed to sign selfie URL:', signError.message);
        doctorAvatar = null;
      } else {
        doctorAvatar = signedData?.signedUrl ?? null;
      }
    }

    console.log('[accept-request] doctorAvatar:', doctorAvatar ? 'signed URL obtained' : 'null');

    const doctorPayload = {
      name: `Dr. ${doctorName}`,
      mdcn: doctorDetails?.mdcn_number ?? 'MDCN/R/00000',
      rating: doctorDetails?.rating ?? 5.0,
      reliability: doctorDetails?.reliability_score ?? 100,
    };

    await Promise.all([
      broadcastToChannel(
        `requester:${request_id}`,
        'MATCH_CONFIRMED',
        { doctor: doctorPayload }
      ),
      broadcastToChannel(
        'dispatch:lagos',
        'EVICT_REQUEST',
        { request_id }
      ),
    ]);

    const reqStartDate = existingRequest.start_date ?? null;
    const reqEndDate = existingRequest.end_date ?? null;

    const startTimeSec = existingRequest.start_time
      ? timeToSeconds(existingRequest.start_time)
      : (reqStartDate ? new Date(reqStartDate).getHours() * 3600 + new Date(reqStartDate).getMinutes() * 60 : 0);
    const endTimeSec = existingRequest.end_time
      ? timeToSeconds(existingRequest.end_time)
      : (reqEndDate ? new Date(reqEndDate).getHours() * 3600 + new Date(reqEndDate).getMinutes() * 60 : 0);

    let bookedSeconds = endTimeSec - startTimeSec;
    if (bookedSeconds <= 0) bookedSeconds += 86400;

    // Fetch pricing rules — single source of truth
    const rules = await fetchPricingRules(serviceClient);

    const incomingCoverageLength = typeof existingRequest.coverage_length === 'number'
