import 'jsr:@supabase/functions-js/edge-runtime.d.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'GET, OPTIONS',
};

function resolvePhone(
  storedPhone: string | null | undefined,
  profilePhone: string | null | undefined,
  authUser: { phone?: string | null; user_metadata?: { phone?: string | null } } | null
): string | null {
  // Prefer the value already stored on the session row — never clobber it with null
  if (storedPhone) return storedPhone;
  // Fall back to live profile lookup
  if (profilePhone) return profilePhone;
  // Last resort: auth user record
  if (authUser?.phone) return authUser.phone;
  if (authUser?.user_metadata?.phone) return authUser.user_metadata.phone;
  return null;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  const supabaseUser = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_ANON_KEY')!,
    { global: { headers: { Authorization: req.headers.get('Authorization')! } } }
  );

  const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
  if (authError || !user) {
    return new Response(JSON.stringify({ error: 'Unauthorized' }), {
      status: 401,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  const url = new URL(req.url);
  const role = url.searchParams.get('role') ?? 'requester';

  const column = role === 'doctor' ? 'doctor_id' : 'requester_id';

  // Doctors need broader coverage so the rating overlay and payment-waiting
  // screens can appear even if the app was backgrounded during a status
  // transition. Requesters only need the narrower set.
  const activeStatuses =
    role === 'doctor'
      ? ['upcoming', 'active', 'paused', 'shift_ended', 'payment_pending', 'requester_paid', 'settled']
      : ['upcoming', 'active', 'paused', 'payment_pending', 'requester_paid'];

  const supabaseAdmin = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );

  const { data, error } = await supabaseAdmin
    .from('coverage_sessions')
    .select('*')
    .eq(column, user.id)
    .in('status', activeStatuses)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) {
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  if (!data) {
    return new Response(JSON.stringify({ session: null }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    });
  }

  // Fetch profiles in parallel — use maybeSingle() so a missing row returns
  // null instead of throwing, and catch auth admin errors gracefully.
  const [
    { data: doctorProfile },
    { data: requesterProfile },
    doctorAuthResult,
    requesterAuthResult,
  ] = await Promise.all([
    supabaseAdmin.from('profiles').select('phone').eq('id', data.doctor_id).maybeSingle(),
    supabaseAdmin.from('profiles').select('phone, rating').eq('id', data.requester_id).maybeSingle(),
    supabaseAdmin.auth.admin.getUserById(data.doctor_id).catch(() => ({ data: { user: null } })),
    supabaseAdmin.auth.admin.getUserById(data.requester_id).catch(() => ({ data: { user: null } })),
  ]);

  const doctorAuthUser = doctorAuthResult?.data?.user ?? null;
  const requesterAuthUser = requesterAuthResult?.data?.user ?? null;

  // Resolve requester rating live from profiles, fall back to stored value
  const requesterRating = requesterProfile?.rating ?? data.requester_rating ?? null;

  const sessionWithPhones = {
    ...data,
    doctor_phone: resolvePhone(data.doctor_phone, doctorProfile?.phone, doctorAuthUser),
    requester_phone: resolvePhone(data.requester_phone, requesterProfile?.phone, requesterAuthUser),
    requester_rating: requesterRating,
  };

  return new Response(JSON.stringify({ session: sessionWithPhones }), {
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
});
