async function broadcastNewRequest(payload: {
  id: string;
  requester_id: string;
  hospital_name: string;
  hospital_address: string;
  shift_type: string;
  shift_date: string | null;
  start_time: string | null;
  end_time: string | null;
  duration_hours: number;
  coverage_length: number | null;
  environment: string;
  note: string | null;
  price: number;
  expiry_at: string;
}): Promise<void> {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

  const response = await fetch(`${supabaseUrl}/realtime/v1/api/broadcast`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${serviceRoleKey}`,
      'Content-Type': 'application/json',
      apikey: serviceRoleKey,
    },
    body: JSON.stringify({
      messages: [
        {
          topic: 'realtime:dispatch:lagos',
          event: 'broadcast',
          payload: {
            type: 'broadcast',
            event: 'NEW_REQUEST',
            payload: {
              id: payload.id,
              requester_id: payload.requester_id,
              hospital_name: payload.hospital_name,
              hospital_address: payload.hospital_address,
              shift_type: payload.shift_type,
              shift_date: payload.shift_date,
              start_time: payload.start_time,
              end_time: payload.end_time,
              duration_hours: payload.duration_hours,
              coverage_length: payload.coverage_length,
              environment: payload.environment,
              note: payload.note,
              price: payload.price,
              expiry_at: payload.expiry_at,
            },
          },
        },
      ],
    }),
  });

  if (!response.ok) {
    const text = await response.text();
    console.error(`Broadcast error [dispatch:lagos]: ${response.status} ${text}`);
  } else {
    console.log('Broadcast NEW_REQUEST sent for request', payload.id, 'expiry_at', payload.expiry_at);
  }
}
