### `calcContinuous` (used by `calculateBill` for straight sessions)
```typescript
function calcContinuous(input: BillingInput): BillingResult {
  const { actualDurationSeconds, bookedDurationSeconds, shiftType, environment, rules } = input;

  const blockSeconds = rules.standard_block_minutes * 60;
  const multiplier = getEnvironmentMultiplier(shiftType, environment, rules);
  const bookedHours = bookedDurationSeconds / 3600;
  const actualHours = actualDurationSeconds / 3600;

  let flatFee: number;
  let lowerBound: number;
  let upperBound: number;

  // Tier selection by bookedHours
  if (bookedHours <= 26) {
    flatFee = rules.straight_24h_flat;
    lowerBound = rules.straight_24h_lower;
    upperBound = rules.straight_24h_upper;
  } else if (bookedHours <= 50) {
    flatFee = rules.straight_48h_flat;
    lowerBound = rules.straight_48h_lower;
    upperBound = rules.straight_48h_upper;
  } else {
    flatFee = rules.straight_72h_flat;
    lowerBound = rules.straight_72h_lower;
    upperBound = rules.straight_72h_upper;
  }

  const perHourRate = flatFee / bookedHours;
  let amountNaira: number;
  let billableSeconds: number;

  if (actualHours < lowerBound) {
    amountNaira = Math.ceil((actualHours * perHourRate * multiplier) / 50) * 50;
    billableSeconds = actualDurationSeconds;
  } else if (actualHours <= upperBound) {
    amountNaira = Math.ceil((flatFee * multiplier) / 50) * 50;
    billableSeconds = lowerBound * 3600;
  } else {
    const overageHours = actualHours - upperBound;
    const roundedOverageSeconds = Math.ceil((overageHours * 3600) / blockSeconds) * blockSeconds;
    const overageNaira = (roundedOverageSeconds / 3600) * perHourRate;
    amountNaira = Math.ceil(((flatFee + overageNaira) * multiplier) / 50) * 50;
    billableSeconds = actualDurationSeconds;
  }

  return {
    billableSeconds,
    billableHours: billableSeconds / 3600,
    amountNaira,
    mode: 'continuous',
    label: formatLabel(billableSeconds),
  };
}
```

