  if (!['active', 'paused'].includes(session.status)) {
    return new Response(
      JSON.stringify({ error: `Cannot end a shift with status: ${session.status}` }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }

  const now = new Date();
  const nowIso = now.toISOString();

  const coverageType = session.coverage_type ?? 'Standard';
  const isStraight = isStraightCoverage(coverageType);
  const coverageLength = Number(session.coverage_length ?? 1);
  const perDayHours = Number(session.per_day_hours ?? 8);
  const currentDay = session.current_day ?? 1;

  const dayLogs: Array<{
    day: number;
    started_at: string;
    paused_at: string | null;
    duration_seconds: number;
    cost?: number;
  }> = [...(session.day_logs ?? [])];

  let finalDayDurationSeconds = 0;

  if (session.status === 'active') {
    const finalDayLogIdx = dayLogs.findIndex(l => l.day === currentDay);
    if (finalDayLogIdx !== -1) {
      const finalDayLog = dayLogs[finalDayLogIdx];
      finalDayDurationSeconds = Math.floor(
        (now.getTime() - new Date(finalDayLog.started_at).getTime()) / 1000
      );
      dayLogs[finalDayLogIdx] = {
