## 1. `end-shift` — Full Source

```typescript
// index.ts (v36)
import { calculateBill, splitNaira, fetchPricingRules, isStraightCoverage,
         calcStandardNaira, calcStraightNaira, resolveHourlyRateFromSession } from './_shared/billing.ts';

// ... (auth, CORS, broadcast helpers omitted for brevity — full source above)

// KEY BILLING LOGIC:

const now = new Date();
const coverageType = session.coverage_type ?? 'Standard';
const isStraight = isStraightCoverage(coverageType);
const coverageLength = Number(session.coverage_length ?? 1);
const perDayHours = Number(session.per_day_hours ?? 8);
const currentDay = session.current_day ?? 1;

// Step 1: Finalize the current day's duration from day_logs
if (session.status === 'active') {
  const finalDayLog = dayLogs.find(l => l.day === currentDay);
  finalDayDurationSeconds = Math.floor(
    (now.getTime() - new Date(finalDayLog.started_at).getTime()) / 1000
  );
  // Fallback: uses session.started_at if no day log found
}

// Step 2: Calculate cost for the final day
if (isStraight) {
  finalDayCostNaira = calcStraightNaira({ actualSeconds, bookedHours, rules });
} else {
  const hourlyRateNaira = resolveHourlyRateFromSession(session, rules);
  finalDayCostNaira = calcStandardNaira({ actualSeconds, bookedHours, hourlyRateNaira, rules });
}

// Step 3: Sum all days
if (session.status === 'paused') {
  finalAmountNaira = dayLogs.reduce((sum, l) => sum + (l.cost ?? 0), 0);
} else {
  finalAmountNaira = completedDaysCost + finalDayCostNaira;
}

// Fallback: if sum is 0, use booked_price
if (finalAmountNaira === 0) finalAmountNaira = session.booked_price ?? session.price ?? 0;
```

