      const straightHours = (totalBookedHours >= 72 ? 72 : totalBookedHours >= 48 ? 48 : 24) as 24 | 48 | 72;
      finalDayCostNaira = calcStraightNaira({
        actualSeconds: finalDayDurationSeconds,
        bookedHours: straightHours,
        rules,
