  };

  await Promise.all([
    broadcastToChannel(`session:${session_id}`, 'SHIFT_ENDED', broadcastPayload),
    broadcastToChannel(`doctor:${session.doctor_id}`, 'SHIFT_ENDED', broadcastPayload),
  ]);

  return new Response(JSON.stringify({
    success: true,
    session: updated,
    total_naira: finalAmountNaira,
    platform_naira: platformNaira,
